  width: 1px;
  background: linear-gradient(180deg, var(--red), rgba(216, 75, 62, 0));
}

.vital-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  font-size: 8px;
  letter-spacing: 0.32em;
  color: var(--bone-dim);
  margin-bottom: 5px;
}

.vital-heading b {
  font-family: var(--display);
  font-weight: 400;
  font-size: 12px;
  letter-spacing: 0.06em;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}

.health-track {
  position: relative;
  height: 13px;
  background: rgba(4, 5, 9, 0.72);
  border: 1px solid rgba(238, 231, 216, 0.12);
  transform: skewX(-14deg);
  overflow: hidden;
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.3);
}

.health-lag,
.health-fill {
  position: absolute;
  top: 1px;
  bottom: 1px;
  left: 1px;
  width: calc(100% - 2px);
  transform-origin: left center;
}

.health-lag {
  background: #f3c2a2;
  opacity: 0.6;
  transition: transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.health-fill {
  background: linear-gradient(90deg, #6d1118 0%, #be2d2d 45%, #f05343 100%);
  box-shadow: 0 0 12px rgba(240, 83, 67, 0.45);
  transition: transform 0.18s ease-out;
}

.health-fill.low {
  background: linear-gradient(90deg, #8c0d15, #f52d39);
  animation: lowHealth 1s ease-in-out infinite;
}

@keyframes lowHealth {
  50% { filter: brightness(1.5); }
}

.health-ticks {
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(5, 6, 10, 0.7) calc(10% - 1px), rgba(5, 6, 10, 0.7) 10%);
  opacity: 0.7;
}

.shadow-track {
  position: relative;
  margin-top: 5px;
  height: 4px;
  width: 243px;
  background: rgba(4, 5, 9, 0.65);
  transform: skewX(-14deg);
  overflow: visible;
}

.shadow-fill {
  position: absolute;
  inset: 0;
  transform-origin: left center;
  background: linear-gradient(90deg, rgba(82, 183, 181, 0.55), var(--cyan));
  box-shadow: 0 0 10px rgba(139, 233, 228, 0.38);
  transition: transform 0.2s ease-out;
}

.shadow-track span {
  position: absolute;
  left: 257px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 7px;
  letter-spacing: 0.26em;
  color: rgba(139, 233, 228, 0.66);
  white-space: nowrap;
}

.shadow-track.full .shadow-fill {
  background: linear-gradient(90deg, #57c5c1, #e8ffff, #ffd694);
  box-shadow: 0 0 18px rgba(139, 233, 228, 0.82);
  animation: shadowReady 1.1s ease-in-out infinite;
}

@keyframes shadowReady {
  50% { filter: brightness(1.55); box-shadow: 0 0 26px rgba(255, 210, 133, 0.9); }
}

.shadow-track.full span {
  color: #ffd694;
}

.combo {
  position: absolute;
  right: 36px;
  top: 25%;
  display: flex;
  align-items: center;
  gap: 10px;
  opacity: 0;
  transform: translateX(15px) rotate(-2deg);
  transition: opacity 0.18s ease, transform 0.22s cubic-bezier(0.2, 0.9, 0.2, 1.2);
}

.combo.visible {
  opacity: 1;
  transform: translateX(0) rotate(-2deg);
}

.combo-number {
  font-family: var(--display);
  font-size: clamp(48px, 7vw, 92px);
  font-weight: 900;
  line-height: 0.8;
  color: transparent;
  -webkit-text-stroke: 1px rgba(238, 231, 216, 0.7);
  background: linear-gradient(180deg, #fff4dc 20%, #df5a4b 75%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 4px 24px rgba(216, 75, 62, 0.3));
}

.combo.pop .combo-number {
  animation: comboPop 0.18s cubic-bezier(0.15, 0.9, 0.2, 1.5);
}

@keyframes comboPop {
  0% { transform: scale(1.45) rotate(2deg); }
  100% { transform: scale(1) rotate(0); }
}

.combo-copy {
  display: flex;
  flex-direction: column;
  margin-top: 9px;
}

.combo-copy b {
  font-family: var(--display);
  font-size: 13px;
  letter-spacing: 0.14em;
  color: var(--bone);
  line-height: 1;
}

.combo-copy span {
  font-size: 8px;
  letter-spacing: 0.34em;
  color: var(--gold);
  margin-top: 3px;
}

.combo-meter {
  position: absolute;
  right: 1px;
  bottom: -10px;
  width: 100%;
  height: 1px;
  background: rgba(238, 231, 216, 0.13);
}

.combo-meter i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: right center;
  background: var(--red);
}

.wave-banner {
  position: absolute;
  left: 50%;
  top: 33%;
  width: min(660px, 84vw);
  transform: translate(-50%, -50%);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0;
  filter: blur(5px);
  transition: opacity 0.3s, filter 0.5s;
}

.wave-banner.show {
  opacity: 1;
  filter: blur(0);
}

.wave-banner span {
  font-size: 9px;
  letter-spacing: 0.6em;
  color: var(--red);
  font-weight: 700;
  transform: translateX(0.3em);
}

.wave-banner strong {
  font-family: var(--display);
  font-size: clamp(26px, 4.2vw, 54px);
  font-weight: 900;
  letter-spacing: 0.12em;
  line-height: 1.08;
  margin: 8px 0 9px;
  color: var(--bone);
  text-shadow: 0 6px 40px rgba(0, 0, 0, 0.9);
}

.wave-banner strong::before,
.wave-banner strong::after {
  content: "";
  display: inline-block;
  width: 35px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--red));
  vertical-align: middle;
  margin: 0 18px;
}

.wave-banner strong::after {
  background: linear-gradient(90deg, var(--red), transparent);
}

.wave-banner em {
  font-family: var(--display);
  font-size: 10px;
  letter-spacing: 0.12em;
  font-style: normal;
  color: rgba(238, 231, 216, 0.55);
}

.boss-bar {
  position: absolute;
  left: 50%;
  bottom: 42px;
  width: min(620px, 64vw);
  transform: translateX(-50%);
  transition: opacity 0.4s;
}

.boss-name {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 6px;
}

.boss-name span {
  font-size: 8px;
  letter-spacing: 0.43em;
  color: var(--red);
  font-weight: 700;
}

.boss-name b {
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.2em;
  font-weight: 900;
}

.boss-track {
  height: 9px;
  background: rgba(2, 3, 6, 0.68);
  border: 1px solid rgba(216, 75, 62, 0.38);
  transform: skewX(-12deg);
}

.boss-track i {
  display: block;
  height: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, #6a1016, #d63835 65%, #ff8a5e);
  box-shadow: 0 0 18px rgba(216, 75, 62, 0.4);
  transition: transform 0.2s;
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 15%;
  transform: translateX(-50%) translateY(10px);
  padding: 7px 18px;
  border-top: 1px solid rgba(201, 165, 104, 0.35);
  border-bottom: 1px solid rgba(201, 165, 104, 0.35);
  background: rgba(4, 5, 9, 0.5);
  color: var(--gold);
  font-size: 10px;
  letter-spacing: 0.28em;
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  white-space: nowrap;
  z-index: 12;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.tutorial {
  position: absolute;
  left: 30px;
  bottom: 28px;
  display: flex;
  gap: 12px;
  align-items: center;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.5s, transform 0.5s;
}

.tutorial.visible {
  opacity: 0.86;
  transform: translateY(0);
}

.tutorial-mark {
  font-family: "Noto Serif JP", "Yu Mincho", serif;
  font-size: 25px;
  color: var(--red);
  opacity: 0.8;
  line-height: 1;
}

.tutorial-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tutorial-copy b {
  font-family: var(--display);
  font-size: 8px;
  letter-spacing: 0.26em;
  color: var(--gold);
}

.tutorial-copy span {
  font-size: 9px;
  letter-spacing: 0.06em;
  color: rgba(238, 231, 216, 0.5);
}

.tutorial-copy kbd {
  display: inline-block;
  padding: 1px 4px;
  border: 1px solid rgba(238, 231, 216, 0.28);
  font-family: var(--ui);
  font-size: 8px;
  color: var(--bone);
  background: rgba(255, 255, 255, 0.04);
}

.tutorial-copy i {
  color: rgba(238, 231, 216, 0.22);
  font-style: normal;
  padding: 0 2px;
}

.pulse-prompt {
  position: absolute;
  left: 50%;
  top: 56%;
  transform: translate(-50%, 0) scale(0.94);
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--cyan);
  font-size: 11px;
  letter-spacing: 0.38em;
  font-weight: 700;
  opacity: 0;
  text-shadow: 0 0 18px rgba(139, 233, 228, 0.7);
  transition: opacity 0.1s, transform 0.2s;
}

.pulse-prompt.show {
  opacity: 1;
  transform: translate(-50%, -8px) scale(1);
}

.pulse-prompt span {
  width: 28px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 12px var(--cyan);
}

/* ------------------------- Touch controls ------------------------- */

.touch-controls {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.3s;
}

.joystick {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  bottom: max(24px, env(safe-area-inset-bottom));
  width: 126px;
  height: 126px;
  pointer-events: auto;
  touch-action: none;
}

.joystick-base {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  border: 1px solid rgba(238, 231, 216, 0.22);
  background: radial-gradient(circle at 50% 45%, rgba(238, 231, 216, 0.07), rgba(4, 5, 9, 0.2) 65%, rgba(4, 5, 9, 0.38));
  box-shadow: inset 0 0 28px rgba(0, 0, 0, 0.42), 0 10px 32px rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(2px);
}

.joy-ring {
  position: absolute;
  inset: 24px;
  border-radius: 50%;
  border: 1px dashed rgba(201, 165, 104, 0.2);
}

.joy-cross {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 20px;
  height: 20px;
  transform: translate(-50%, -50%);
  opacity: 0.32;
}

.joy-cross::before,
.joy-cross::after {
  content: "";
  position: absolute;
  background: rgba(238, 231, 216, 0.5);
}

.joy-cross::before { left: 50%; top: 0; width: 1px; height: 100%; }
.joy-cross::after { top: 50%; left: 0; height: 1px; width: 100%; }

.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  border: 1px solid rgba(238, 231, 216, 0.5);
  background: radial-gradient(circle at 42% 35%, rgba(255, 255, 255, 0.18), rgba(12, 14, 20, 0.8));
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.45), inset 0 0 16px rgba(139, 233, 228, 0.1);
  display: grid;
  place-items: center;
  transition: box-shadow 0.15s;
  will-change: transform;
}

.joystick.active .joystick-knob {
  border-color: rgba(139, 233, 228, 0.7);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5), inset 0 0 18px rgba(139, 233, 228, 0.3), 0 0 24px rgba(139, 233, 228, 0.14);
}

.joystick-knob i {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: rgba(238, 231, 216, 0.5);
  box-shadow: 0 0 10px rgba(139, 233, 228, 0.3);
}

.action-cluster {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(22px, env(safe-area-inset-bottom));
  width: 190px;
  height: 190px;
  pointer-events: none;
}

.action-btn {
  position: absolute;
  pointer-events: auto;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  border: 1px solid rgba(238, 231, 216, 0.3);
  background: radial-gradient(circle at 40% 32%, rgba(238, 231, 216, 0.17), rgba(6, 7, 11, 0.72) 68%);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.3), inset 0 0 18px rgba(0, 0, 0, 0.26);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  color: var(--bone);
  touch-action: none;
  backdrop-filter: blur(2px);
  transition: transform 0.08s, border-color 0.12s, background 0.12s;
}

.action-btn svg {
  width: 24px;
  height: 24px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.3;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.9;
}

.action-btn span {
  font-size: 6px;
  letter-spacing: 0.16em;
  font-weight: 700;
  opacity: 0.8;
}

.action-btn:active,
.action-btn.pressed {
  transform: scale(0.9);
  border-color: rgba(255, 226, 166, 0.9);
  background: radial-gradient(circle at 40% 32%, rgba(216, 75, 62, 0.45), rgba(6, 7, 11, 0.8) 70%);
}

.attack-action {
  width: 82px;
  height: 82px;
  right: 0;
  bottom: 10px;
  border-color: rgba(216, 75, 62, 0.58);
  box-shadow: 0 8px 34px rgba(0, 0, 0, 0.35), inset 0 0 22px rgba(216, 75, 62, 0.12);
}

.attack-action svg {
  width: 31px;
  height: 31px;
}

.dash-action {
  right: 89px;
  bottom: 35px;
  border-color: rgba(139, 233, 228, 0.38);
}

.kunai-action {
  right: 54px;
  bottom: 101px;
}

.shadow-action {
  right: 0;
  bottom: 103px;
  width: 56px;
  height: 56px;
  border-color: rgba(201, 165, 104, 0.38);
  opacity: 0.66;
}

.shadow-action.ready {
  opacity: 1;
  border-color: rgba(255, 214, 148, 0.85);
  color: #ffe4ad;
  box-shadow: 0 0 24px rgba(255, 202, 116, 0.25), inset 0 0 20px rgba(255, 202, 116, 0.17);
  animation: readyPulse 1.3s ease-in-out infinite;
}

@keyframes readyPulse {
  50% { box-shadow: 0 0 32px rgba(255, 202, 116, 0.48), inset 0 0 24px rgba(255, 202, 116, 0.28); }
}

.shadow-action svg { width: 20px; height: 20px; }
.shadow-action span { font-size: 5px; }

.action-btn.cooldown {
  opacity: 0.4;
}

/* --------------------------- Screens --------------------------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  transition: opacity 0.45s ease, visibility 0.45s ease;
}

.title-screen {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background:
    linear-gradient(90deg, rgba(3, 4, 8, 0.93) 0%, rgba(3, 4, 8, 0.72) 35%, rgba(3, 4, 8, 0.1) 74%, transparent 100%),
    radial-gradient(ellipse at 72% 46%, transparent 10%, rgba(2, 3, 6, 0.16) 60%, rgba(2, 3, 6, 0.55) 100%);
  padding: clamp(20px, 3.2vw, 48px) clamp(24px, 5vw, 76px);
}

.title-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(0deg, rgba(3, 4, 8, 0.8), transparent 24%);
}

.title-top {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.title-mark {
  display: flex;
  align-items: center;
  gap: 12px;
}

.title-mark span {
  display: grid;
  place-items: center;
  width: 31px;
  height: 35px;
  border: 1px solid rgba(216, 75, 62, 0.75);
  color: var(--red);
  font-family: "Noto Serif JP", "Yu Mincho", serif;
  font-size: 19px;
  line-height: 1;
  transform: rotate(-2deg);
}

.title-mark i {
  width: 25px;
  height: 1px;
  background: rgba(238, 231, 216, 0.24);
}

.title-mark b {
  font-size: 9px;
  letter-spacing: 0.32em;
  color: rgba(238, 231, 216, 0.55);
  font-weight: 600;
}

.title-best {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
  text-align: right;
}

.title-best span {
  font-size: 7px;
  letter-spacing: 0.38em;
  color: var(--bone-dim);
}

.title-best b {
  font-family: var(--display);
  font-size: 14px;
  letter-spacing: 0.12em;
  color: var(--gold);
  font-weight: 400;
}

.title-content {
  position: relative;
  z-index: 2;
  max-width: 690px;
  padding-bottom: 1.4vh;
  animation: titleIn 1.1s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes titleIn {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 13px;
  font-size: 9px;
  letter-spacing: 0.44em;
  color: var(--gold);
  font-weight: 600;
  text-transform: uppercase;
}

.eyebrow i {
  width: 32px;
  height: 1px;
  background: var(--red);
  box-shadow: 0 0 8px rgba(216, 75, 62, 0.4);
}

.eyebrow.blood { color: var(--red); }
.eyebrow.gold { color: var(--gold); }

h1 {
  margin: 0;
  display: flex;
  flex-direction: column;
  line-height: 0.78;
  font-family: var(--display);
  font-weight: 900;
}

.title-shadow,
.title-ninja {
  display: block;
  white-space: nowrap;
}

.title-shadow {
  font-size: clamp(64px, 8.8vw, 136px);
  letter-spacing: 0.035em;
  color: var(--bone);
  text-shadow:
    0 1px 0 rgba(255, 255, 255, 0.2),
    0 10px 60px rgba(0, 0, 0, 0.55),
    0 0 80px rgba(238, 231, 216, 0.04);
}

.title-ninja {
  font-size: clamp(82px, 11.7vw, 176px);
  letter-spacing: 0.14em;
  color: transparent;
  -webkit-text-stroke: 1px rgba(238, 231, 216, 0.66);
  background: linear-gradient(180deg, rgba(216, 75, 62, 0.07) 8%, rgba(216, 75, 62, 0.78) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  text-shadow: 0 12px 55px rgba(118, 19, 20, 0.2);
  margin-left: 0.07em;
  margin-top: 0.09em;
  position: relative;
}

.title-ninja::after {
  content: "忍";
  position: absolute;
  left: calc(100% + 0.28em);
  bottom: 0.1em;
  width: 0.38em;
  height: 0.42em;
  display: grid;
  place-items: center;
  font-size: 0.24em;
  color: var(--red);
  border: 1px solid rgba(216, 75, 62, 0.85);
  -webkit-text-stroke: 0;
  background: rgba(3, 4, 8, 0.5);
  transform: rotate(3deg);
  letter-spacing: 0;
  font-family: "Noto Serif JP", "Yu Mincho", serif;
  font-weight: 400;
}

.title-rule {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 310px;
  margin: 28px 0 17px;
}

.title-rule i {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(216, 75, 62, 0.65), transparent);
}

.title-rule i:last-child {
  background: linear-gradient(90deg, transparent, rgba(216, 75, 62, 0.65));
}

.title-rule span {
  display: grid;
  place-items: center;
  color: var(--bone-dim);
  font-family: "Noto Serif JP", "Yu Mincho", serif;
  font-size: 14px;
  width: 27px;
  height: 27px;
  border: 1px solid rgba(238, 231, 216, 0.22);
  transform: rotate(45deg);
}

.title-rule span::first-line {
  transform: rotate(-45deg);
}

.title-blurb {
  margin: 0 0 27px;
  max-width: 430px;
  font-family: var(--display);
  font-size: clamp(12px, 1.05vw, 15px);
  line-height: 1.7;
  letter-spacing: 0.035em;
  color: rgba(238, 231, 216, 0.64);
}

.title-actions {
  display: flex;
  align-items: center;
  gap: 13px;
}

.btn {
  position: relative;
  border: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  height: 52px;
  padding: 0 31px;
  font-size: 11px;
  letter-spacing: 0.28em;
  font-weight: 700;
  text-transform: uppercase;
  transition: transform 0.18s, background 0.2s, color 0.2s, border-color 0.2s;
}

.btn::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(5, 6, 10, 0.12);
  pointer-events: none;
  transition: inset 0.2s, border-color 0.2s;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-primary {
  background: var(--bone);
  color: #0b0c10;
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.3);
  clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 0 100%);
}

.btn-primary:hover {
  background: #fff8e9;
}

