      y: initial ? rand(view.H * 0.96, -30) : rand(-40, -140),
      vx: rand(24, -42), vy: rand(39, 13), sway: rand(22, 5),
      phase: rand(TAU), size: front ? rand(8, 3.2) : rand(5.5, 2),
      spin: rand(2.3, -2.3), rot: rand(TAU), front,
      color: chance(0.3) ? '#c54a3d' : chance(0.5) ? '#8f2e2c' : '#6d2831'
    };
  }

  // ---------------------------------------------------------------------------
  // Ambient
  // ---------------------------------------------------------------------------
  function updateScenery(dt) {
    if (!ambient) buildScenery();
    const W = view.W, H = view.H;
    for (const p of ambient.petals) {
      p.phase += dt * 1.2;
      p.x += (p.vx + Math.sin(p.phase) * p.sway) * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
      if (p.y > H + 30 || p.x < -110 || p.x > W + 110) Object.assign(p, makePetal(false));
    }
    for (const f of ambient.fireflies) {
      f.phase += dt * 1.6;
      f.x += Math.cos(f.phase * 0.7) * f.drift * dt;
      f.y += Math.sin(f.phase) * f.speed * dt;
      if (f.x < -20) f.x = W + 20;
      if (f.x > W + 20) f.x = -20;
      if (f.y < H * 0.25) f.y = H * 0.85;
      if (f.y > H * 0.94) f.y = H * 0.3;
    }
    for (const e of ambient.embers) {
      e.life -= dt * 0.18;
      e.x += e.vx * dt;
      e.y -= e.vy * dt;
      if (e.life <= 0 || e.y < H * 0.25) {
        e.x = rand(W); e.y = H * rand(0.92, 0.55); e.life = rand(1, 0.5);
      }
    }
  }

  function drawPetal(p, scale = 1) {
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.rot);
    ctx.scale(scale, scale * 0.58);
    ctx.fillStyle = p.color;
    ctx.globalAlpha = p.front ? 0.5 : 0.34;
    ctx.beginPath();
    ctx.moveTo(-p.size * 0.5, 0);
    ctx.quadraticCurveTo(0, -p.size * 0.55, p.size * 0.55, 0);
    ctx.quadraticCurveTo(0, p.size * 0.35, -p.size * 0.5, 0);
    ctx.fill();
    ctx.restore();
  }

  function drawAmbient(front = false) {
    if (!ambient) return;
    for (const p of ambient.petals) {
      if (p.front === front) drawPetal(p, p.front ? 1.25 : 0.9);
    }
    if (!front) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (const f of ambient.fireflies) {
        const pulse = 0.3 + Math.max(0, Math.sin(f.phase * 1.8)) * 0.7;
        const g = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.size * 9);
        g.addColorStop(0, `rgba(160,255,215,${0.28 * pulse})`);
        g.addColorStop(1, 'rgba(80,200,170,0)');
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.arc(f.x, f.y, f.size * 9, 0, TAU); ctx.fill();
        ctx.fillStyle = `rgba(210,255,228,${0.65 * pulse})`;
        ctx.beginPath(); ctx.arc(f.x, f.y, f.size * 0.65, 0, TAU); ctx.fill();
      }
      for (const e of ambient.embers) {
        const a = clamp(e.life, 0, 1) * 0.45;
        ctx.fillStyle = `rgba(255,166,88,${a})`;
        ctx.beginPath(); ctx.arc(e.x, e.y, e.size, 0, TAU); ctx.fill();
        ctx.fillStyle = `rgba(255,96,46,${a * 0.28})`;
        ctx.beginPath(); ctx.arc(e.x, e.y, e.size * 4.5, 0, TAU); ctx.fill();
      }
      ctx.restore();
    }
  }

  // ---------------------------------------------------------------------------
  // Sky, moon, mountains
  // ---------------------------------------------------------------------------
  function drawSky() {
    const W = view.W, H = view.H, S = view.scale;
    const sky = ctx.createLinearGradient(0, 0, 0, H * 0.6);
    sky.addColorStop(0, '#03050b');
    sky.addColorStop(0.38, '#090914');
    sky.addColorStop(0.72, '#17101b');
    sky.addColorStop(1, '#2a151d');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, W, H);

    // Stars
    for (const s of scenery.stars) {
      const tw = 0.55 + Math.sin(G.time * 0.75 + s.phase) * 0.45;
      ctx.globalAlpha = s.a * tw;
      ctx.fillStyle = '#e8e5dd';
      ctx.beginPath();
      ctx.arc(s.nx * W, s.ny * H, s.size, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Aurora-like dust band
    ctx.save();
    const band = ctx.createLinearGradient(0, H * 0.13, W, H * 0.34);
    band.addColorStop(0, 'rgba(88,42,64,0)');
    band.addColorStop(0.45, 'rgba(113,49,62,0.055)');
    band.addColorStop(1, 'rgba(45,50,80,0)');
    ctx.fillStyle = band;
    ctx.beginPath();
    ctx.moveTo(0, H * 0.2);
    ctx.bezierCurveTo(W * 0.3, H * 0.11, W * 0.5, H * 0.3, W, H * 0.18);
    ctx.lineTo(W, H * 0.31);
    ctx.bezierCurveTo(W * 0.55, H * 0.4, W * 0.3, H * 0.2, 0, H * 0.32);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    drawMoon(W, H, S);

    // Clouds
    for (const c of scenery.clouds) {
      const drift = ((c.nx + G.time * c.speed) % 1.35) - 0.16;
      const x = drift * W;
      const y = c.ny * H + Math.sin(G.time * 0.04 + c.phase) * 5 * S;
      const cw = c.w * W, ch = c.h * H;
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(1, ch / cw);
      const g = ctx.createRadialGradient(0, 0, 0, 0, 0, cw);
      g.addColorStop(0, `rgba(113,103,121,${c.a})`);
      g.addColorStop(0.55, `rgba(68,63,80,${c.a * 0.7})`);
      g.addColorStop(1, 'rgba(35,34,47,0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(0, 0, cw, 0, TAU); ctx.fill();
      ctx.restore();
    }

    drawMountains(W, H, S);
  }

  function drawMoon(W, H, S) {
    const mx = W * (W < 700 ? 0.73 : 0.715);
    const my = H * (W < 700 ? 0.215 : 0.235);
    const R = Math.min(W, H) * (W < 700 ? 0.16 : 0.17);
    const pulse = 1 + Math.sin(G.time * 0.33) * 0.012;

    ctx.save();
    const halo = ctx.createRadialGradient(mx, my, R * 0.2, mx, my, R * 4.2);
    halo.addColorStop(0, 'rgba(219,91,67,0.27)');
    halo.addColorStop(0.28, 'rgba(174,57,52,0.12)');
    halo.addColorStop(0.68, 'rgba(79,36,58,0.045)');
    halo.addColorStop(1, 'rgba(20,20,42,0)');
    ctx.fillStyle = halo;
    ctx.beginPath(); ctx.arc(mx, my, R * 4.2, 0, TAU); ctx.fill();

    // outer eclipse ring
    ctx.strokeStyle = 'rgba(255,142,103,0.09)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(mx, my, R * 1.21, 0, TAU); ctx.stroke();

    const moon = ctx.createRadialGradient(mx - R * 0.32, my - R * 0.34, R * 0.1, mx, my, R * pulse);
    moon.addColorStop(0, '#ffd9a4');
    moon.addColorStop(0.34, '#f6a36e');
    moon.addColorStop(0.7, '#dc5b49');
    moon.addColorStop(1, '#a6333a');
    ctx.fillStyle = moon;
    ctx.beginPath(); ctx.arc(mx, my, R * pulse, 0, TAU); ctx.fill();

    // craters
    ctx.save();
    ctx.beginPath(); ctx.arc(mx, my, R, 0, TAU); ctx.clip();
    const craters = [
      [-0.36, -0.22, 0.24, 0.18], [0.14, -0.38, 0.14, 0.13],
      [0.28, 0.16, 0.27, 0.22], [-0.18, 0.34, 0.16, 0.12],
      [-0.61, 0.2, 0.1, 0.08], [0.48, -0.16, 0.08, 0.06]
    ];
    for (const [x, y, rx, ry] of craters) {
      const g = ctx.createRadialGradient(mx + x * R, my + y * R, 0, mx + x * R, my + y * R, rx * R);
      g.addColorStop(0, 'rgba(115,40,45,0.22)');
      g.addColorStop(0.75, 'rgba(150,52,47,0.11)');
      g.addColorStop(1, 'rgba(255,190,140,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(mx + x * R, my + y * R, rx * R, ry * R, 0.35, 0, TAU);
      ctx.fill();
    }
    // veil clouds across moon
    const veil = ctx.createLinearGradient(0, my - R * 0.15, 0, my + R * 0.7);
    veil.addColorStop(0, 'rgba(32,27,39,0)');
    veil.addColorStop(0.52, 'rgba(34,28,40,0.38)');
    veil.addColorStop(1, 'rgba(22,20,32,0.62)');
    ctx.fillStyle = veil;
    ctx.beginPath();
    ctx.moveTo(mx - R, my + R * 0.12);
    ctx.bezierCurveTo(mx - R * 0.4, my - R * 0.08, mx + R * 0.2, my + R * 0.3, mx + R, my + R * 0.04);
    ctx.lineTo(mx + R, my + R); ctx.lineTo(mx - R, my + R);
    ctx.closePath(); ctx.fill();
    ctx.restore();
    ctx.restore();
  }

  function drawMountains(W, H, S) {
    const horizon = HORIZON * S;
    const offset = -G.cam.x * 0.035 * S;
    ctx.save();
    ctx.translate(offset, 0);

    const drawRidge = (peaks, color, scaleY, lift) => {
      ctx.beginPath();
      ctx.moveTo(-W * 0.25, horizon + 100 * S);
      for (const p of peaks) {
        const x = p.x * W;
        const y = (p.y * H) * 0.92 - lift * S;
        ctx.lineTo(x, y);
      }
      ctx.lineTo(W * 1.4, horizon + 110 * S);
      ctx.lineTo(W * 1.4, horizon + 170 * S);
      ctx.lineTo(-W * 0.25, horizon + 170 * S);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
    };

    drawRidge(scenery.farPeaks, '#0e0d19', 1, 58);
    const haze = ctx.createLinearGradient(0, horizon * 0.82, 0, horizon + 30 * S);
    haze.addColorStop(0, 'rgba(104,74,91,0)');
    haze.addColorStop(0.7, 'rgba(110,70,83,0.1)');
    haze.addColorStop(1, 'rgba(78,57,74,0.2)');
    ctx.fillStyle = haze;
    ctx.fillRect(-W * 0.3, horizon * 0.8, W * 1.8, horizon * 0.26);

    drawRidge(scenery.midPeaks, '#080a11', 1, 12);

    // far temple roof silhouette
    drawShrineSilhouette(W * 0.16 + offset * 0.35, horizon + 25 * S, S * 0.7);
    // the gate is the visual anchor
    drawTorii(W * 0.815 + offset * 0.85, horizon + 58 * S, S * 0.98);
    ctx.restore();
  }

  function drawShrineSilhouette(x, base, s) {
    ctx.save();
    ctx.translate(x, base);
    ctx.scale(s, s);
    const fill = '#090b10';
    ctx.fillStyle = fill;
    ctx.fillRect(-120, -40, 250, 42);
    ctx.fillRect(-96, -150, 15, 116);
    ctx.fillRect(72, -150, 15, 116);
    ctx.fillRect(-70, -145, 10, 111);
    ctx.fillRect(50, -145, 10, 111);
    // eaves
    for (let i = 0; i < 3; i++) {
      const y = -150 - i * 62, w = 175 - i * 28;
      ctx.beginPath();
      ctx.moveTo(-w, y);
      ctx.quadraticCurveTo(-w * 0.55, y - 24, 0, y - 30);
      ctx.quadraticCurveTo(w * 0.55, y - 24, w, y);
      ctx.lineTo(w * 0.92, y + 10);
      ctx.quadraticCurveTo(0, y - 11, -w * 0.92, y + 10);
      ctx.closePath();
      ctx.fill();
    }
    ctx.fillStyle = 'rgba(168,95,62,0.42)';
    ctx.fillRect(-92, -126, 7, 24);
    ctx.fillRect(59, -126, 7, 24);
    ctx.restore();
  }

  function drawTorii(x, base, s) {
    ctx.save();
    ctx.translate(x, base);
    ctx.scale(s, s);
    const top = -412;
    // glow behind gate
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(0, -238, 20, 0, -238, 230);
    glow.addColorStop(0, 'rgba(191,61,49,0.11)');
    glow.addColorStop(1, 'rgba(151,38,42,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(-260, -520, 520, 530);
    ctx.restore();

    ctx.fillStyle = '#190d11';
    ctx.strokeStyle = 'rgba(144,49,49,0.55)';
    ctx.lineWidth = 1.2;

    // pillars
    for (const px of [-112, 112]) {
      ctx.beginPath();
      ctx.moveTo(px - 16, 0);
      ctx.lineTo(px - 11, top + 68);
      ctx.quadraticCurveTo(px - 9, top + 44, px - 14, top + 38);
      ctx.lineTo(px + 14, top + 38);
      ctx.quadraticCurveTo(px + 9, top + 44, px + 11, top + 68);
      ctx.lineTo(px + 16, 0);
      ctx.closePath();
      ctx.fill(); ctx.stroke();
    }

    // top beam, curved
    ctx.beginPath();
    ctx.moveTo(-192, top + 42);
    ctx.quadraticCurveTo(-140, top + 24, -72, top + 28);
    ctx.lineTo(72, top + 28);
    ctx.quadraticCurveTo(140, top + 24, 192, top + 42);
    ctx.lineTo(180, top + 58);
    ctx.quadraticCurveTo(120, top + 42, 70, top + 44);
    ctx.lineTo(-70, top + 44);
    ctx.quadraticCurveTo(-120, top + 42, -180, top + 58);
    ctx.closePath();
    ctx.fill(); ctx.stroke();

    // roof cap
    ctx.fillStyle = '#0d090c';
    ctx.beginPath();
    ctx.moveTo(-206, top + 30);
    ctx.quadraticCurveTo(-150, top + 10, -60, top + 16);
    ctx.lineTo(60, top + 16);
    ctx.quadraticCurveTo(150, top + 10, 206, top + 30);
    ctx.lineTo(197, top + 39);
    ctx.quadraticCurveTo(140, top + 23, 62, top + 27);
    ctx.lineTo(-62, top + 27);
    ctx.quadraticCurveTo(-140, top + 23, -197, top + 39);
    ctx.closePath();
    ctx.fill();

    // second beam
    ctx.fillStyle = '#1d0e12';
    ctx.fillRect(-142, top + 105, 284, 15);
    ctx.strokeRect(-142, top + 105, 284, 15);
    ctx.fillRect(-9, top + 42, 18, 66);

    // plaque
    ctx.fillStyle = '#0c090b';
    ctx.fillRect(-30, top + 70, 60, 50);
    ctx.strokeStyle = 'rgba(201,165,104,0.5)';
    ctx.strokeRect(-30, top + 70, 60, 50);
    ctx.fillStyle = 'rgba(201,165,104,0.75)';
    ctx.font = '31px "Noto Serif JP", serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('影', 0, top + 97);

    // rope and shide
    ctx.strokeStyle = 'rgba(184,163,126,0.42)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-130, top + 126);
    ctx.bezierCurveTo(-70, top + 142, 20, top + 114, 92, top + 130);
    ctx.stroke();
    for (let i = 0; i < 4; i++) {
      const sx = -104 + i * 53, sy = top + 135 + Math.sin(i) * 4;
      ctx.strokeStyle = 'rgba(211,195,164,0.4)';
      ctx.beginPath();
      ctx.moveTo(sx, sy); ctx.lineTo(sx + 3, sy + 20);
      ctx.lineTo(sx - 4, sy + 28); ctx.lineTo(sx + 2, sy + 38);
      ctx.stroke();
    }

    // hanging tattered banners
    ctx.fillStyle = 'rgba(91,19,24,0.58)';
    ctx.beginPath();
    ctx.moveTo(-78, top + 122);
    ctx.lineTo(-56, top + 123);
    ctx.lineTo(-58, top + 222);
    ctx.lineTo(-70, top + 208);
    ctx.lineTo(-76, top + 226);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(117,26,29,0.38)';
    ctx.fillRect(62, top + 124, 16, 83);

    // base stones
    ctx.fillStyle = '#07080b';
    ctx.beginPath(); ctx.ellipse(-112, 3, 34, 9, 0, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(112, 3, 34, 9, 0, 0, TAU); ctx.fill();
    ctx.restore();
  }

  // ---------------------------------------------------------------------------
  // Midground bamboo
  // ---------------------------------------------------------------------------
  function drawBamboo(screenSpace = false) {
    const W = view.W, H = view.H, S = view.scale;
    const horizon = HORIZON * S;
    const list = screenSpace ? scenery.foregroundBamboo : scenery.bamboo;
    const offset = -G.cam.x * (screenSpace ? 0.085 : 0.03) * S;
    for (const b of list) {
      const x = ((b.nx * W + offset) % (W * 1.35) + W * 1.35) % (W * 1.35) - W * 0.1;
      if (x < -80 || x > W + 80) continue;
      const height = b.h * H;
      const sway = Math.sin(G.time * 0.35 + b.phase) * (screenSpace ? 7 : 4) * S;
      ctx.save();
      ctx.translate(x, horizon + 35 * S);
      ctx.rotate(b.lean);
      const w = b.w * (screenSpace ? S * 1.8 : S);
      const col = screenSpace ? '#030607' : (b.tone > 0.65 ? '#071310' : '#050d0b');
      ctx.strokeStyle = col;
      ctx.lineWidth = w;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(sway * 0.3, -height * 0.4, sway, -height * 0.75, sway * 1.8, -height);
      ctx.stroke();
      // node highlights
      if (!screenSpace) {
        ctx.strokeStyle = 'rgba(62,98,78,0.22)';
        ctx.lineWidth = Math.max(0.5, w * 0.18);
        for (let i = 1; i < 6; i++) {
          const yy = -height * (i / 6.4);
          const xx = sway * (i / 6.4) * 1.1;
          ctx.beginPath();
          ctx.moveTo(xx - w * 0.7, yy); ctx.lineTo(xx + w * 0.7, yy);
          ctx.stroke();
        }
      }
      // leaves
      const lc = screenSpace ? '#020405' : 'rgba(10,28,21,0.9)';
      ctx.fillStyle = lc;
      for (let i = 0; i < b.leaf; i++) {
        const t = 0.42 + i * 0.09;
        const lx = sway * t * 1.6;
        const ly = -height * t;
        const dir = i % 2 ? 1 : -1;
        const len = (screenSpace ? 35 : 18) * S * (0.7 + (i % 3) * 0.2);
        ctx.save();
        ctx.translate(lx, ly);
        ctx.rotate(dir * (0.35 + i * 0.22) + Math.sin(G.time + b.phase + i) * 0.03);
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(dir * len * 0.65, -len * 0.28, dir * len, 0);
        ctx.quadraticCurveTo(dir * len * 0.6, len * 0.1, 0, 0);
        ctx.fill();
        ctx.restore();
      }
      ctx.restore();
    }
  }

  // ---------------------------------------------------------------------------
  // Ground
  // ---------------------------------------------------------------------------
  function drawGround() {
    const S = view.scale, W = view.W, H = view.H;
    ctx.save();
    worldTransform(1, 0.7);
    const top = HORIZON;
    const g = ctx.createLinearGradient(0, top, 0, 900);
    g.addColorStop(0, '#0d1113');
    g.addColorStop(0.18, '#121518');
    g.addColorStop(0.55, '#090c0f');
    g.addColorStop(1, '#040609');
    ctx.fillStyle = g;
    ctx.fillRect(-1800, top - 8, 6200, 1000);

    // faint stone path boundary
    ctx.fillStyle = 'rgba(84,69,61,0.06)';
    ctx.beginPath();
    ctx.moveTo(-1800, top + 2);
    ctx.lineTo(4400, top + 2);
    ctx.lineTo(4400, top + 18);
    ctx.lineTo(-1800, top + 18);
    ctx.closePath(); ctx.fill();

    // red moon reflection on the wet courtyard
    const reflectX = G.cam.x + (W * 0.715 - W / 2) / S;
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const rg = ctx.createRadialGradient(reflectX, top + 82, 2, reflectX, top + 82, 310);
    rg.addColorStop(0, 'rgba(189,69,47,0.1)');
    rg.addColorStop(0.35, 'rgba(122,46,45,0.055)');
    rg.addColorStop(1, 'rgba(73,37,58,0)');
    ctx.fillStyle = rg;
    ctx.beginPath(); ctx.ellipse(reflectX, top + 94, 330, 120, 0, 0, TAU); ctx.fill();
    ctx.restore();

    // stones
    for (const st of scenery.stones) {
      const y = groundY(st.z);
      if (st.x < G.cam.x - view.half - 110 || st.x > G.cam.x + view.half + 110) continue;
      const ds = depthScale(st.z);
      ctx.save();
      ctx.translate(st.x, y + 1);
      ctx.rotate(st.rot);
      ctx.beginPath();
      ctx.ellipse(0, 0, st.w * ds * 0.5, st.h * ds * 0.36, 0, 0, TAU);
      ctx.fillStyle = st.tone > 0.75 ? 'rgba(84,78,69,0.13)' : 'rgba(46,47,45,0.22)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(156,143,121,0.045)';
      ctx.lineWidth = 0.7;
      ctx.stroke();
      ctx.restore();
    }

    // puddles
    for (const p of scenery.puddles) {
      if (p.x < G.cam.x - view.half - 250 || p.x > G.cam.x + view.half + 250) continue;
      const y = groundY(p.z), ds = depthScale(p.z);
      ctx.save();
      ctx.translate(p.x, y + 2);
      ctx.scale(1, 0.18);
      const pg = ctx.createRadialGradient(0, 0, 0, 0, 0, p.w * ds);
      pg.addColorStop(0, `rgba(155,76,62,${p.a * 0.65})`);
      pg.addColorStop(0.55, `rgba(65,69,76,${p.a})`);
      pg.addColorStop(1, 'rgba(24,29,34,0)');
      ctx.fillStyle = pg;
      ctx.beginPath(); ctx.arc(0, 0, p.w * ds, 0, TAU); ctx.fill();
      ctx.strokeStyle = 'rgba(197,137,107,0.07)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(0, 0, p.w * ds * 0.6, 0.2, 2.4); ctx.stroke();
      ctx.restore();
    }

    // fallen leaves
    for (const l of scenery.leaves) {
      if (l.x < G.cam.x - view.half - 80 || l.x > G.cam.x + view.half + 80) continue;
      const y = groundY(l.z);
      ctx.save();
      ctx.translate(l.x, y);
      ctx.rotate(l.rot);
      ctx.fillStyle = l.tone > 0.5 ? 'rgba(135,43,42,0.44)' : 'rgba(95,39,43,0.32)';
      ctx.beginPath();
      ctx.ellipse(0, 0, l.size, l.size * 0.35, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // grass tufts
    for (const gr of scenery.grass) {
      if (gr.x < G.cam.x - view.half - 100 || gr.x > G.cam.x + view.half + 100) continue;
      const y = groundY(gr.z), ds = depthScale(gr.z);
      ctx.save();
      ctx.translate(gr.x, y);
      ctx.strokeStyle = gr.tone > 0.6 ? 'rgba(50,68,46,0.5)' : 'rgba(31,48,38,0.55)';
      ctx.lineWidth = 1.2 * ds;
      for (let i = 0; i < gr.blades; i++) {
        const angle = -1.55 + (i - gr.blades / 2) * 0.3 + Math.sin(G.time * 0.7 + gr.phase + i) * 0.04;
        const leng = gr.h * ds;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(Math.cos(angle) * leng * 0.3, -leng * 0.55, Math.cos(angle) * leng * 0.75, -leng);
        ctx.stroke();
      }
      ctx.restore();
    }

    // Lanterns and their glow
    for (const l of [{ x: 330, z: 0.9 }, { x: 1490, z: 0.92 }, { x: 2280, z: 0.86 }]) {
      if (l.x < G.cam.x - view.half - 200 || l.x > G.cam.x + view.half + 200) continue;
      drawLantern(l.x, l.z);
    }

    // low courtyard haze
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const fogX = G.cam.x;
    const fog = ctx.createLinearGradient(-500, top + 3, 2000, top + 40);
    fog.addColorStop(0, 'rgba(96,111,120,0)');
    fog.addColorStop(0.45, 'rgba(107,119,129,0.055)');
    fog.addColorStop(1, 'rgba(83,96,110,0)');
    ctx.fillStyle = fog;
    ctx.fillRect(fogX - view.half, top + 2, view.w, 38);
    ctx.restore();

    ctx.restore();
  }

  function drawLantern(x, z) {
    const y = groundY(z), ds = depthScale(z);
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(ds * 1.05, ds * 1.05);

    // ground light
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const groundGlow = ctx.createRadialGradient(0, -18, 1, 0, -18, 100);
    groundGlow.addColorStop(0, 'rgba(255,157,76,0.15)');
    groundGlow.addColorStop(1, 'rgba(210,87,43,0)');
    ctx.fillStyle = groundGlow;
    ctx.beginPath(); ctx.ellipse(0, 0, 100, 25, 0, 0, TAU); ctx.fill();

    const glow = ctx.createRadialGradient(0, -85, 1, 0, -85, 85);
    glow.addColorStop(0, 'rgba(255,194,110,0.45)');
    glow.addColorStop(0.4, 'rgba(255,117,55,0.12)');
    glow.addColorStop(1, 'rgba(255,80,30,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(0, -85, 85, 0, TAU); ctx.fill();
    ctx.restore();

    // base
    ctx.fillStyle = '#0b0d0e';
    ctx.beginPath();
    ctx.moveTo(-18, 0); ctx.lineTo(18, 0); ctx.lineTo(14, -13); ctx.lineTo(-14, -13); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#151819';
    ctx.fillRect(-8, -53, 16, 41);
    ctx.fillStyle = '#0d1011';
    ctx.fillRect(-15, -61, 30, 9);
    // light chamber
    ctx.fillStyle = '#181818';
    ctx.fillRect(-18, -96, 36, 32);
    ctx.fillStyle = 'rgba(255,171,82,0.85)';
    ctx.fillRect(-11, -90, 22, 20);
    ctx.fillStyle = 'rgba(255,229,171,0.9)';
    ctx.fillRect(-5, -88, 10, 16);
    // cap
    ctx.fillStyle = '#0b0d0e';
    ctx.beginPath();
    ctx.moveTo(-30, -100); ctx.quadraticCurveTo(0, -122, 30, -100);
    ctx.lineTo(23, -91); ctx.quadraticCurveTo(0, -106, -23, -91); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#212325';
    ctx.beginPath(); ctx.arc(0, -124, 4, 0, TAU); ctx.fill();
    // warm flicker
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const t = G.time * 4 + x;
    const f = 0.7 + Math.sin(t) * 0.12 + Math.sin(t * 2.3) * 0.08;
    ctx.fillStyle = `rgba(255,203,123,${0.22 * f})`;
    ctx.beginPath(); ctx.arc(0, -80, 17, 0, TAU); ctx.fill();
    ctx.restore();
    ctx.restore();
  }

  // ---------------------------------------------------------------------------
  // Foreground
  // ---------------------------------------------------------------------------
  function drawForegroundFog() {
    const W = view.W, H = view.H, S = view.scale;
    ctx.save();
    const g = ctx.createLinearGradient(0, H * 0.72, 0, H);
    g.addColorStop(0, 'rgba(7,12,16,0)');
    g.addColorStop(0.55, 'rgba(6,10,13,0.22)');
    g.addColorStop(1, 'rgba(3,5,8,0.7)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 3; i++) {
      const x = ((G.time * (8 + i * 4) + i * 360) % (W + 700)) - 350;
      const y = H * (0.67 + i * 0.07);
      const gr = ctx.createRadialGradient(x, y, 0, x, y, 300 * S);
      gr.addColorStop(0, 'rgba(100,123,132,0.025)');
      gr.addColorStop(1, 'rgba(70,91,106,0)');
      ctx.fillStyle = gr;
      ctx.beginPath(); ctx.ellipse(x, y, 300 * S, 60 * S, 0, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  // ---------------------------------------------------------------------------
  // Exports
  // ---------------------------------------------------------------------------
  Object.assign(window, {
    buildScenery, updateScenery, drawSky, drawGround, drawBamboo,
    drawForegroundFog, drawAmbient, drawLantern
  });
})();

(() => {
  'use strict';

  // ---------------------------------------------------------------------------
  // FX helpers
  // ---------------------------------------------------------------------------
  function spawnParticle(o) {
    if (G.particles.length > 520) G.particles.shift();
    G.particles.push(Object.assign({
      x: 0, y: 0, z: 0.6, vx: 0, vy: 0, gravity: 0, drag: 0.98,
      life: 0.5, maxLife: 0.5, size: 2, color: '#fff', kind: 'spark',
      rot: rand(TAU), spin: rand(4, -4), alpha: 1, glow: false
    }, o));
  }

  function spawnImpact(x, y, z, color = '#ffe6b4', count = 10, power = 1) {
    for (let i = 0; i < count; i++) {
      const a = rand(TAU);
      const sp = rand(420, 90) * power;
      spawnParticle({
        x, y, z, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 30,
        gravity: 620, drag: 0.92, life: rand(0.38, 0.14),
        maxLife: 0.4, size: rand(3.5, 1), color, kind: chance(0.7) ? 'spark' : 'ink', glow: true
      });
    }
    for (let i = 0; i < Math.ceil(count * 0.45); i++) {
      const a = rand(TAU);
      spawnParticle({
        x, y, z, vx: Math.cos(a) * rand(75, 12), vy: rand(-6, -55),
        gravity: 20, drag: 0.9, life: rand(0.8, 0.35), maxLife: 0.8,
        size: rand(14, 4), color: chance(0.5) ? 'rgba(13,14,20,0.75)' : color,
        kind: 'smoke', alpha: 0.22
      });
    }
  }

  function spawnDeath(e) {
    const s = depthScale(e.z);
    const y = groundY(e.z) - 75 * s;
    const count = e.cfg.boss ? 48 : e.cfg.superArmor ? 28 : 18;
    const colors = e.cfg.boss ? ['#ffd18b', '#e3503e', '#23151a'] : ['#d9c4a4', '#a62f31', '#151018'];
    for (let i = 0; i < count; i++) {
      const a = rand(TAU), sp = rand(300, 30) * (e.cfg.boss ? 1.4 : 1);
      spawnParticle({
        x: e.x + rand(20, -20), y: y + rand(30, -30), z: e.z,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 60, gravity: 480,
        drag: 0.95, life: rand(1.25, 0.4), maxLife: 1.3,
        size: rand(5, 1), color: colors[randInt(0, colors.length - 1)],
        kind: chance(0.25) ? 'petal' : chance(0.5) ? 'ink' : 'spark', glow: chance(0.5)
      });
    }
    for (let i = 0; i < 10; i++) {
      const a = rand(TAU);
      spawnParticle({
        x: e.x, y: y + rand(40), z: e.z, vx: Math.cos(a) * rand(110, 20), vy: rand(-70, -20),
        gravity: 10, life: rand(1.1, 0.5), maxLife: 1.1, size: rand(24, 8),
        color: '#0a0b10', kind: 'smoke', alpha: 0.25
      });
    }
    if (e.cfg.boss) {
      G.effects.push({ type: 'ring', x: e.x, y: groundY(e.z), z: e.z, life: 1.0, maxLife: 1.0, r: 40, maxR: 420, color: '#ffb66e', width: 8 });
      flash('#ffc27b', 0.55);
      addShake(18);
    }
  }

  function spawnGhost(p, life = 0.32, color = '#7de4df') {
    G.effects.push({
      type: 'ghost', x: p.x, y: groundY(p.z), z: p.z, facing: p.facing,
      life, maxLife: life, color, state: p.state, anim: p.anim, attackStep: p.attackStep,
      timer: p.timer
    });
  }

  function spawnSlash(p, step, life = 0.2) {
    const facing = p.facing;
    const data = step === 1
      ? { from: -2.1, to: 0.9, radius: 118, color: '#f6f1dd' }
      : step === 2
        ? { from: 2.25, to: -1.15, radius: 126, color: '#bff5ed' }
        : { from: -2.8, to: 2.7, radius: 155, color: '#ffd8a1' };
    G.effects.push({
      type: 'slash', x: p.x, y: groundY(p.z) - 92 * depthScale(p.z), z: p.z,
      facing, from: data.from, to: data.to, radius: data.radius,
      life, maxLife: life, color: data.color, step
    });
  }

  function spawnEnemySlash(e) {
    const facing = e.facing;
    G.effects.push({
      type: 'eslash', x: e.x, y: groundY(e.z) - 84 * depthScale(e.z), z: e.z,
      facing, from: -1.9, to: 1.3, radius: e.cfg.boss ? 175 : 105,
      life: 0.26, maxLife: 0.26, color: e.cfg.boss ? '#ff9b63' : '#ca4b43', step: 1
    });
  }

  function spawnRing(x, z, color = '#f0c584', maxR = 180, life = 0.45) {
    G.effects.push({ type: 'ring', x, y: groundY(z), z, life, maxLife: life, r: 10, maxR, color, width: 3 });
  }

  function addFloatText(text, x, y, z, color = '#f3e7d0', size = 18) {
    G.texts.push({ text, x: x + rand(12, -12), y, z, color, size, life: 0.9, maxLife: 0.9, vy: -55 });
  }

  // ---------------------------------------------------------------------------
  // Damage & rewards
  // ---------------------------------------------------------------------------
  function damageEnemy(enemy, amount, opts = {}) {
    if (!enemy || enemy.dead || enemy.state === 'spawn') return;
    const wasHp = enemy.hp;
    const killed = enemy.hurt(amount, opts.source || G.player, opts);
    G.combo += 1;
    G.comboTimer = 2.5;
    G.bestCombo = Math.max(G.bestCombo, G.combo);
    G.player.shadow = clamp(G.player.shadow + (opts.shadow || 6), 0, 100);
    G.score += Math.round(amount * 10 * (1 + G.combo * 0.055));
    const s = depthScale(enemy.z);
    const hy = groundY(enemy.z) - 92 * s;
    addFloatText(String(Math.round(amount)), enemy.x, hy - 20, enemy.z, opts.heavy ? '#ffcc8e' : '#f5ead5', opts.heavy ? 24 : 18);
    spawnImpact(enemy.x, hy, enemy.z, killColor(enemy), opts.heavy ? 15 : 9, opts.heavy ? 1.4 : 0.9);
    addShake(opts.shake ?? (opts.heavy ? 7 : 3));
    if (!opts.noHitstop) G.hitstop = Math.max(G.hitstop, opts.stop ?? (opts.heavy ? 0.07 : 0.035));
    audio.hit(!!opts.heavy);
    if (killed) {
      onEnemyKilled(enemy);
    }
    return killed;
  }

  function killColor(e) {
    if (e.type === 'archer') return '#b8e6c5';
    if (e.type === 'brute' || e.type === 'boss') return '#ffb575';
    if (e.type === 'spear') return '#e6b3a0';
    return '#f3d8b6';
  }

  function onEnemyKilled(enemy) {
    G.kills++;
    const bonus = enemy.cfg.score;
    G.score += Math.round(bonus * (1 + G.combo * 0.04));
    G.player.shadow = clamp(G.player.shadow + (enemy.cfg.boss ? 45 : 12), 0, 100);
    G.player.hp = Math.min(G.player.maxHp, G.player.hp + (enemy.cfg.boss ? 0 : 2));
    spawnDeath(enemy);
    audio.kill();
    G.hitstop = Math.max(G.hitstop, enemy.cfg.boss ? 0.14 : 0.075);
    addShake(enemy.cfg.boss ? 16 : 8);
    if (enemy.cfg.boss) {
      slowTime(1.25);
      flash('#ffe0b0', 0.8);
      G.victoryTimer = 2.4;
    } else if (enemy.cfg.superArmor) {
      slowTime(0.45);
    }
    if (G.combo > 0 && G.combo % 10 === 0) {
      showToast(`${G.combo} HIT CHAIN  ·  +${G.combo * 12} SHADOW`);
      G.player.shadow = clamp(G.player.shadow + 8, 0, 100);
    }
  }

  // ---------------------------------------------------------------------------
  // Player
  // ---------------------------------------------------------------------------
  class Player {
    constructor(x = 760, z = 0.55) {
      this.x = x;
      this.z = z;
      this.facing = 1;
      this.maxHp = 100;
      this.hp = 100;
      this.shadow = 0;
      this.state = 'idle';
      this.timer = 0;
      this.anim = rand(4);
      this.runPhase = 0;
      this.attackStep = 0;
      this.queued = false;
      this.attackHit = false;
      this.dashCd = 0;
      this.kunaiCd = 0;
      this.iframe = 0;
      this.flash = 0;
      this.dead = false;
      this.ghostTimer = 0;
      this.dustTimer = 0;
      this.perfectThisDash = false;
      this.dashDirX = 1;
      this.dashDirZ = 0;
      this.specialTargets = [];
      this.specialIndex = 0;
      this.specialNext = 0;
      this.specialOrigin = { x, z };
      this.lastDamage = 0;
      this.stepPhase = 0;
    }

    get invulnerable() {
      return this.iframe > 0 || this.state === 'dash' || this.state === 'special';
    }

    update(dt) {
      this.anim += dt;
      this.flash = Math.max(0, this.flash - dt * 5);
      this.iframe = Math.max(0, this.iframe - dt);
      this.dashCd = Math.max(0, this.dashCd - dt);
      this.kunaiCd = Math.max(0, this.kunaiCd - dt);
      if (this.dead) return;

      if (this.state === 'attack') return this.updateAttack(dt);
      if (this.state === 'dash') return this.updateDash(dt);
      if (this.state === 'kunai') return this.updateKunai(dt);
      if (this.state === 'special') return this.updateSpecial(dt);
      if (this.state === 'hurt') {
        this.timer += dt;
        if (this.timer > 0.28) { this.state = 'idle'; this.timer = 0; }
        return;
      }
      this.updateMovement(dt);
    }

    updateMovement(dt) {
      const axis = input.axis();
      const ax = axis.x, az = axis.y;
      if (Math.abs(ax) > 0.18) this.facing = sign(ax);

      // Ability input order matters while cancelling.
      if (input.consume('special') && this.shadow >= 100 && G.enemies.some(e => !e.dead)) {
        this.startSpecial();
        return;
      }
      if (input.consume('dash') && this.dashCd <= 0) {
        this.startDash(ax, az);
        return;
      }
      if (input.consume('kunai') && this.kunaiCd <= 0) {
        this.startKunai();
        return;
      }
      if (input.consume('attack') || input.held.attack) {
        this.startAttack(1);
        return;
      }

      const speed = 270;
      const dzSpeed = 155;
      const moving = Math.hypot(ax, az) > 0.08;
      if (moving) {
        this.x += ax * speed * dt;
        this.z += az * dzSpeed * dt;
        this.state = 'run';
        this.runPhase += dt * (8.5 + Math.hypot(ax, az) * 4);
        this.dustTimer -= dt;
        if (this.dustTimer <= 0) {
          this.dustTimer = 0.13;
          spawnParticle({
            x: this.x + rand(14, -14), y: groundY(this.z) - 2, z: this.z,
            vx: -ax * rand(40, 8) + rand(12, -12), vy: rand(-24, -6), gravity: -10,
            life: rand(0.5, 0.25), maxLife: 0.5, size: rand(10, 3),
            color: 'rgba(173,164,148,0.35)', kind: 'dust', drag: 0.94
          });
        }
      } else {
        this.state = 'idle';
        this.runPhase += dt * 1.5;
      }
      this.clampPosition();
    }

    clampPosition() {
      this.x = clamp(this.x, 120, ARENA_W - 120);
      this.z = clamp(this.z, FLOOR_Z.min, FLOOR_Z.max);
    }

    startAttack(step) {
      const spec = ATTACKS[step - 1];
      this.state = 'attack';
      this.attackStep = step;
      this.timer = 0;
      this.attackHit = false;
      this.queued = false;
      this.stepPhase = 0;
      audio.slash(step - 1);
      if (step === 3) {
        // The finisher begins with a low, coiled stance.
        spawnRing(this.x, this.z, '#f3d3a2', 95, 0.3);
      }
      // Stick to the target direction on startup.
      if (Math.abs(input.axis().x) > 0.2) this.facing = sign(input.axis().x);
      this.lungeRemaining = spec.lunge;
    }

    updateAttack(dt) {
      const spec = ATTACKS[this.attackStep - 1];
      this.timer += dt;
      const p = this.timer;
      // forward lunge
      if (p < spec.startup + spec.active) {
        this.x += this.facing * spec.lunge * dt * 1.8;
        this.clampPosition();
      }
      if (!this.attackHit && p >= spec.startup) {
        this.attackHit = true;
        this.performAttack(spec);
        spawnSlash(this, this.attackStep, this.attackStep === 3 ? 0.27 : 0.2);
        if (this.attackStep === 3) {
          addShake(6);
          G.effects.push({ type: 'ring', x: this.x, y: groundY(this.z), z: this.z, life: 0.36, maxLife: 0.36, r: 20, maxR: 170, color: '#ffe1b1', width: 2 });
        }
      }
      // Allow dash-cancel after the active frames for fluid defense.
      if (p > spec.startup + spec.active * 0.55 && input.consume('dash') && this.dashCd <= 0) {
        this.startDash(input.axis().x, input.axis().y);
        return;
      }
      if (input.consume('attack') && p > 0.04) this.queued = true;
      if (p > spec.startup + spec.active + spec.recover) {
        if (this.queued && this.attackStep < 3) {
          this.startAttack(this.attackStep + 1);
        } else {
          this.state = 'idle';
          this.timer = 0;
        }
      }
    }

    performAttack(spec) {
      let hitAny = false;
      for (const e of G.enemies) {
        if (!e || e.dead || e.state === 'spawn') continue;
        const dx = e.x - this.x;
        const dz = e.z - this.z;
        const forward = this.attackStep === 3 || dx * this.facing > -24;
        if (!forward) continue;
        if (Math.abs(dx) < spec.reach * (this.attackStep === 3 ? 1.05 : 1) && Math.abs(dz) < spec.zReach) {
          const heavy = this.attackStep === 3;
          const killed = damageEnemy(e, spec.damage * (1 + G.combo * 0.012), {
            source: this, heavy, shadow: heavy ? 10 : 6,
            stop: spec.stop, shake: spec.shake,
            knockback: heavy ? 62 : this.attackStep === 2 ? 36 : 24
          });
          hitAny = true;
          if (killed && this.attackStep < 3) this.queued = true;
          // small forward drag on impact
          this.x += this.facing * (heavy ? 10 : 4);
        }
      }
      if (hitAny && chance(0.35)) flash('rgba(255,244,218,0.08)', 0.1);
      this.clampPosition();
    }

    startDash(ax, az) {
      if (this.dashCd > 0) return;
      let dx = ax, dz = az;
      if (Math.hypot(dx, dz) < 0.15) { dx = this.facing; dz = 0; }
      const m = Math.hypot(dx, dz) || 1;
      this.dashDirX = dx / m;
      this.dashDirZ = dz / m;
      if (Math.abs(this.dashDirX) > 0.1) this.facing = sign(this.dashDirX);
      this.state = 'dash';
      this.timer = 0;
      this.dashCd = 0.52;
      this.iframe = 0.24;
      this.perfectThisDash = false;
      this.ghostTimer = 0;
      audio.dash();
      spawnRing(this.x, this.z, 'rgba(137,236,229,0.9)', 70, 0.3);
      for (let i = 0; i < 8; i++) {
        spawnParticle({
          x: this.x + rand(18, -18), y: groundY(this.z) - rand(80, 10), z: this.z,
          vx: -this.dashDirX * rand(220, 80) + rand(30, -30), vy: rand(20, -80),
          gravity: 140, drag: 0.9, life: rand(0.4, 0.15), maxLife: 0.4,
          size: rand(9, 2), color: chance(0.5) ? '#82dad4' : '#e9dcc2', kind: 'spark', glow: true
        });
      }
    }

    updateDash(dt) {
      this.timer += dt;
      const speed = 790 * (1 - this.timer * 1.2);
      this.x += this.dashDirX * speed * dt;
      this.z += this.dashDirZ * speed * 0.36 * dt;
      this.clampPosition();
      this.ghostTimer -= dt;
      if (this.ghostTimer <= 0) {
        this.ghostTimer = 0.027;
        spawnGhost(this, 0.26, '#5fd8d1');
      }
      if (this.timer > 0.19) {
        this.state = 'idle';
        this.timer = 0;
      }
    }

    startKunai() {
      if (this.kunaiCd > 0) return;
      this.state = 'kunai';
      this.timer = 0;
      this.kunaiCd = 0.48;
      this.thrown = false;
    }

    updateKunai(dt) {
      this.timer += dt;
      if (!this.thrown && this.timer >= 0.08) {
        this.thrown = true;
        G.projectiles.push({
          kind: 'kunai', x: this.x + this.facing * 34, z: this.z,
          vx: this.facing * 900, life: 1.1, maxLife: 1.1,
          spin: 0, owner: 'player', damage: 7 + G.combo * 0.2
        });
        audio.kunai();
        for (let i = 0; i < 3; i++) {
          spawnParticle({
            x: this.x + this.facing * 35, y: groundY(this.z) - 100, z: this.z,
            vx: this.facing * rand(130, 40), vy: rand(20, -20), gravity: 0,
            life: 0.25, maxLife: 0.25, size: rand(4, 1), color: '#b9f3ec', kind: 'spark', glow: true
          });
        }
      }
      if (this.timer > 0.27) { this.state = 'idle'; this.timer = 0; }
    }

    startSpecial() {
      if (this.shadow < 100) return;
      const targets = G.enemies.filter(e => !e.dead && e.state !== 'spawn')
        .sort((a, b) => dist2(a.x, a.z * 200, this.x, this.z * 200) - dist2(b.x, b.z * 200, this.x, this.z * 200));
      if (!targets.length) return;
      this.shadow = 0;
      this.state = 'special';
      this.timer = 0;
      this.specialTargets = targets.slice(0, 8);
      this.specialIndex = 0;
      this.specialNext = 0.09;
      this.iframe = 2.2;
      this.specialOrigin = { x: this.x, z: this.z };
      audio.special();
      audio.bossRoar();
      flash('#9cf6ee', 0.5);
      slowTime(0.55);
      addShake(10);
      spawnRing(this.x, this.z, '#a7f5ee', 240, 0.65);
    }

    updateSpecial(dt) {
      this.timer += dt;
      this.specialNext -= dt;
      if (this.specialNext <= 0) {
        const target = this.specialTargets[this.specialIndex];
        this.specialIndex++;
        this.specialNext = 0.085;
        if (target && !target.dead) {
          const oldX = this.x, oldZ = this.z;
          const side = target.x > ARENA_W / 2 ? -1 : 1;
          this.x = clamp(target.x + side * 48, 100, ARENA_W - 100);
          this.z = clamp(target.z + rand(0.04, -0.04), FLOOR_Z.min, FLOOR_Z.max);
          this.facing = sign(target.x - this.x) || 1;
          spawnGhost({ ...this, x: oldX, z: oldZ, state: 'dash', anim: this.anim, attackStep: 1 }, 0.45, '#8ff8ef');
          for (let i = 0; i < 2; i++) {
            spawnGhost(this, 0.38, '#b3fff6');
          }
          spawnSlash(this, 2, 0.3);
          spawnImpact(target.x, groundY(target.z) - 90, target.z, '#a5fff4', 14, 1.3);
          damageEnemy(target, 19, {
            source: this, heavy: true, noHitstop: true, shadow: 0, stop: 0, shake: 3,
            knockback: 22
          });
          G.hitstop = Math.max(G.hitstop, 0.018);
          addShake(4);
          flash('rgba(170,255,244,0.09)', 0.08);
        }
        if (this.specialIndex >= this.specialTargets.length || !this.specialTargets.some(t => !t.dead)) {
          this.finishSpecial();
        }
      }
      if (this.timer > 1.5) this.finishSpecial();
    }

    finishSpecial() {
      this.state = 'idle';
      this.iframe = 0.55;
      this.timer = 0;
      this.x = clamp(this.x, 120, ARENA_W - 120);
      spawnRing(this.x, this.z, '#b8fff7', 300, 0.7);
      flash('#c8fff9', 0.4);
      addShake(14);
      audio.hit(true);
      G.shadowBurst = 0.6;
    }

    takeDamage(amount, source) {
      if (this.dead) return false;
      if (this.state === 'dash' || this.state === 'special') {
        if (this.state === 'dash' && !this.perfectThisDash) {
          this.perfectThisDash = true;
          this.iframe = Math.max(this.iframe, 0.14);
          this.perfectDodge(source);
        }
        return false;
      }
      if (this.iframe > 0) return false;
      this.hp = Math.max(0, this.hp - amount);
      this.lastDamage = amount;
      this.iframe = 0.58;
      this.state = 'hurt';
      this.timer = 0;
      this.flash = 1;
      this.queued = false;
      const dir = sign(this.x - (source?.x ?? this.x));
      this.x = clamp(this.x + dir * 20, 120, ARENA_W - 120);
      spawnImpact(this.x, groundY(this.z) - 92, this.z, '#e65242', 16, 1.1);
      addFloatText(`-${Math.round(amount)}`, this.x, groundY(this.z) - 150, this.z, '#ff7866', 20);
      flash('#c6232c', 0.4);
      addShake(12);
      G.hitstop = Math.max(G.hitstop, 0.075);
      audio.hurt();
      G.combo = 0;
      G.comboTimer = 0;
      if (this.hp <= 0) this.die();
      return true;
    }

    perfectDodge(source) {
      this.shadow = clamp(this.shadow + 25, 0, 100);
      slowTime(0.8);
      flash('#9ff7f2', 0.35);
      addShake(3);
      audio.perfect();
      G.perfectTimer = 0.8;
      G.score += 75;
      spawnRing(this.x, this.z, '#9ff7f2', 220, 0.6);
      for (let i = 0; i < 16; i++) {
        spawnParticle({
          x: this.x + rand(20, -20), y: groundY(this.z) - rand(120, 10), z: this.z,
          vx: rand(260, -260), vy: rand(80, -200), gravity: 300,
          life: rand(0.55, 0.2), maxLife: 0.55, size: rand(3, 1),
          color: chance(0.5) ? '#b9fff9' : '#f4e4c5', kind: 'spark', glow: true
        });
      }
      addFloatText('PERFECT', this.x, groundY(this.z) - 175, this.z, '#a8fff8', 22);
    }

    die() {
      this.dead = true;
      this.state = 'dead';
      this.timer = 0;
      G.deathTimer = 1.4;
      slowTime(1.1);
      flash('#b51d2a', 0.55);
      addShake(16);
      spawnImpact(this.x, groundY(this.z) - 85, this.z, '#da3d36', 30, 1.5);
      for (let i = 0; i < 24; i++) {
        spawnParticle({
          x: this.x + rand(30, -30), y: groundY(this.z) - rand(140, 10), z: this.z,
          vx: rand(220, -220), vy: rand(-20, -220), gravity: 400,
          life: rand(1.1, 0.4), maxLife: 1.1, size: rand(14, 2),
          color: chance(0.5) ? '#10121a' : '#d8453d', kind: chance(0.4) ? 'smoke' : 'ink'
        });
      }
    }

    // Preview-only shimmering idle used behind the title.
    previewUpdate(dt) {
      this.anim += dt;
      this.runPhase += dt * 1.2;
    }
  }

  // ---------------------------------------------------------------------------
  // Enemy
  // ---------------------------------------------------------------------------
  class Enemy {
    constructor(type, x, z, wave = 0) {
      this.type = type;
      this.cfg = ENEMY_TYPES[type];
      this.x = x;
      this.z = clamp(z, FLOOR_Z.min, FLOOR_Z.max);
      this.facing = -1;
      this.maxHp = Math.round(this.cfg.hp + (this.cfg.boss ? wave * 18 : wave * 3.2));
      this.hp = this.maxHp;
      this.state = 'spawn';
      this.timer = 0;
      this.spawnDuration = 0.48;
      this.anim = rand(5);
      this.runPhase = rand(10);
      this.windupT = this.cfg.windup;
      this.strikeT = this.cfg.strike;
      this.recoverT = this.cfg.recover;
      this.cooldown = rand(1.4, 0.45);
      this.think = rand(1.2, 0.2);
      this.strafe = chance(0.5) ? 1 : -1;
      this.dead = false;
      this.flash = 0;
      this.didHit = false;
      this.hpBar = 0;
      this.speed = this.cfg.speed * rand(1.08, 0.92);
      this.enraged = false;
      this.shadowTrail = 0;
      this.wave = wave;
    }

    get alive() { return !this.dead; }

    update(dt) {
      this.anim += dt;
      this.flash = Math.max(0, this.flash - dt * 6);
      this.hpBar = Math.max(0, this.hpBar - dt * 0.24);
      if (this.dead) {
        this.timer += dt;
        return;
      }
      if (this.state === 'spawn') {
        this.timer += dt;
        if (this.timer >= this.spawnDuration) {
          this.state = 'idle';
          this.timer = 0;
        }
        return;
      }
      this.cooldown = Math.max(0, this.cooldown - dt);
      this.think -= dt;

      if (this.state === 'hurt') {
        this.timer += dt;
        if (this.timer > (this.cfg.superArmor ? 0.2 : 0.3)) { this.state = 'idle'; this.timer = 0; }
        return;
      }
      if (this.state === 'windup') {
        this.timer += dt;
        if (this.timer >= this.windupT) {
          this.state = 'strike';
          this.timer = 0;
          this.didHit = false;
        }
        return;
      }
      if (this.state === 'strike') {
        this.timer += dt;
        if (!this.didHit && this.timer >= this.strikeT * 0.3) {
          this.didHit = true;
          this.doAttack();
        }
        if (this.timer >= this.strikeT + 0.05) {
          this.state = 'recover';
          this.timer = 0;
        }
        return;
      }
      if (this.state === 'recover') {
        this.timer += dt;
        if (this.timer >= this.recoverT) { this.state = 'idle'; this.timer = 0; }
        return;
      }

      // Approach / spacing / strafing
      const dx = G.player.x - this.x;
      const dz = G.player.z - this.z;
      const adx = Math.abs(dx), adz = Math.abs(dz);
      const desired = this.cfg.ranged ? 280 : this.type === 'spear' ? 118 : this.type === 'brute' ? 94 : this.type === 'boss' ? 138 : 66;
      let mx = 0, mz = 0;
      if (adx > desired + 12) mx = sign(dx);
      else if (adx < desired - 30) mx = -sign(dx);
      // archers and everyone else circle a little
      if (this.think <= 0) {
        this.think = rand(2.2, 0.8);
        this.strafe = chance(0.5) ? 1 : -1;
      }
      const strafeFactor = this.cfg.ranged ? 0.45 : 0.26;
      mz = clamp(dz * 2.2 + this.strafe * strafeFactor, -1, 1);
      if (Math.abs(dz) < 0.1) mz *= 0.4;

      // separation from allies
      for (const other of G.enemies) {
        if (other === this || other.dead || other.state === 'spawn') continue;
        const odx = this.x - other.x, odz = this.z - other.z;
        if (Math.abs(odx) < 48 && Math.abs(odz) < 0.12) {
          mx += sign(odx || 1) * 0.7;
          mz += sign(odz || 1) * 0.3;
        }
      }

      const spd = this.speed * (this.enraged ? 1.35 : 1);
      if (Math.abs(mx) > 0.03 || Math.abs(mz) > 0.04) {
        this.x += clamp(mx, -1, 1) * spd * dt;
        this.z += clamp(mz, -1, 1) * spd * 0.35 * dt;
        this.state = 'walk';
        this.runPhase += dt * 6.5;
      } else {
        this.state = 'idle';
      }
      this.facing = dx >= 0 ? 1 : -1;
      this.x = clamp(this.x, 100, ARENA_W - 100);
      this.z = clamp(this.z, FLOOR_Z.min, FLOOR_Z.max);

      if (this.cfg.boss && !this.enraged && this.hp < this.maxHp * 0.42) {
        this.enraged = true;
        this.cooldown = 0.2;
        this.speed *= 1.18;
        G.effects.push({ type: 'ring', x: this.x, y: groundY(this.z), z: this.z, life: 0.8, maxLife: 0.8, r: 30, maxR: 260, color: '#ff7f54', width: 5 });
        flash('#ff6d4d', 0.24);
        addShake(10);
        audio.bossRoar();
        showToast('THE ONI SHOGUN IS ENRAGED');
      }

      const inRange = adx < this.cfg.range * (this.enraged ? 1.25 : 1.12) && adz < this.cfg.zReach * 1.25;
      if (this.cooldown <= 0 && inRange && this.think < 1.3) {
        this.state = 'windup';
        this.timer = 0;
        this.windupT = this.cfg.windup * (this.enraged ? 0.72 : 1) * rand(1.08, 0.9);
        this.cooldown = this.cfg.cooldown * (this.enraged ? 0.7 : 1) * rand(1.25, 0.85);
      }
    }

    doAttack() {
      const dx = Math.abs(G.player.x - this.x);
      const dz = Math.abs(G.player.z - this.z);
      const isArcher = this.type === 'archer';
      if (isArcher) {
        const px = G.player.x, pz = G.player.z;
        const angle = Math.atan2((pz - this.z) * 150, px - this.x);
        G.projectiles.push({
          kind: 'arrow', x: this.x + this.facing * 24, z: this.z,
          vx: Math.cos(angle) * 430, vz: Math.sin(angle) * 0.42 * 430,
          life: 2.3, maxLife: 2.3, spin: 0, owner: 'enemy', damage: this.cfg.damage
        });
        audio.kunai();
        spawnParticle({
          x: this.x + this.facing * 25, y: groundY(this.z) - 104, z: this.z,
          vx: this.facing * 50, vy: -15, life: 0.3, maxLife: 0.3, size: 8,
          color: '#d64b41', kind: 'spark', glow: true
        });
        return;
      }

      spawnEnemySlash(this);
      if (this.type === 'brute' || this.cfg.boss) {
        const r = this.cfg.boss ? 185 : 128;
        spawnRing(this.x, this.z, this.cfg.boss ? '#ff8358' : '#e5b078', r * 1.4, 0.5);
        addShake(this.cfg.boss ? 10 : 7);
        if (dx < r && dz < 0.55) {
          G.player.takeDamage(this.cfg.damage, this);
        }
        for (let i = 0; i < 16; i++) {
          const a = rand(TAU);
          spawnParticle({
            x: this.x + Math.cos(a) * 20, y: groundY(this.z) - 4, z: this.z,
            vx: Math.cos(a) * rand(220, 50), vy: rand(-40, -150), gravity: 500,
            life: rand(0.7, 0.25), maxLife: 0.7, size: rand(9, 2),
            color: chance(0.5) ? '#7f654a' : '#b04339', kind: 'dust'
          });
        }
        return;
      }
      // sword / spear
      if (dx < this.cfg.range * 1.16 && dz < this.cfg.zReach * 1.2) {
        G.player.takeDamage(this.cfg.damage, this);
      }
      addShake(3);
    }

    hurt(amount, source, opts = {}) {
      if (this.dead) return false;
      this.hp -= amount;
      this.flash = 0.16;
      this.hpBar = 3.2;
      const dir = source ? sign(this.x - source.x || 1) : 1;
      this.x = clamp(this.x + dir * (opts.knockback || 18), 100, ARENA_W - 100);
      if (this.hp <= 0) {
        this.hp = 0;
        this.dead = true;
        this.state = 'dead';
        this.timer = 0;
        return true;
      }
      if (!this.cfg.superArmor || opts.heavy) {
        this.state = 'hurt';
        this.timer = 0;
        if (this.cfg.superArmor) {
          this.x += dir * 8;
        }
      }
      return false;
    }
  }

  // ---------------------------------------------------------------------------
  // Projectiles
  // ---------------------------------------------------------------------------
  function updateProjectiles(dt) {
    for (let i = G.projectiles.length - 1; i >= 0; i--) {
      const p = G.projectiles[i];
      p.x += p.vx * dt;
      p.z += (p.vz || 0) * dt;
      p.life -= dt;
      p.spin += dt * 18;
      let hit = false;
      if (p.owner === 'player') {
        for (const e of G.enemies) {
          if (e.dead || e.state === 'spawn') continue;
          if (Math.abs(p.x - e.x) < 25 && Math.abs(p.z - e.z) < 0.17) {
            damageEnemy(e, p.damage, { source: G.player, shadow: 2, shake: 2, stop: 0.025 });
            spawnImpact(e.x, groundY(e.z) - 84, e.z, '#bff9f2', 7, 0.8);
            hit = true;
            break;
          }
        }
      } else {
        if (!G.player.dead && Math.abs(p.x - G.player.x) < 22 && Math.abs(p.z - G.player.z) < 0.17) {
          G.player.takeDamage(p.damage, p);
          hit = true;
        }
      }
      if (p.life <= 0 || hit || p.x < -80 || p.x > ARENA_W + 80 || p.z < 0 || p.z > 1.1) {
        if (!hit && p.owner === 'player') {
          spawnParticle({
            x: p.x, y: groundY(p.z) - 90, z: p.z, vx: 0, vy: -10,
            life: 0.35, maxLife: 0.35, size: 8, color: '#9be8e1', kind: 'spark', glow: true
          });
        }
        G.projectiles.splice(i, 1);
      }
    }
  }

  function updateParticles(dt) {
    for (let i = G.particles.length - 1; i >= 0; i--) {
      const p = G.particles[i];
      p.life -= dt;
      if (p.life <= 0) { G.particles.splice(i, 1); continue; }
      p.vy += (p.gravity || 0) * dt;
      p.vx *= Math.pow(p.drag || 0.98, dt * 60);
      p.vy *= Math.pow(p.drag || 0.98, dt * 60);
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
    }
  }

  function updateEffects(dt) {
    for (let i = G.effects.length - 1; i >= 0; i--) {
      const e = G.effects[i];
      e.life -= dt;
      if (e.type === 'ring') e.r = lerp(e.r, e.maxR, 1 - Math.pow(0.001, dt));
      if (e.life <= 0) G.effects.splice(i, 1);
    }
    for (let i = G.texts.length - 1; i >= 0; i--) {
      const t = G.texts[i];
      t.life -= dt;
      t.y += t.vy * dt;
      t.vy *= 0.96;
      if (t.life <= 0) G.texts.splice(i, 1);
    }
  }

  Object.assign(window, {
    spawnParticle, spawnImpact, spawnDeath, spawnGhost, spawnSlash, spawnEnemySlash,
    spawnRing, addFloatText, damageEnemy, onEnemyKilled, Player, Enemy,
    updateProjectiles, updateParticles, updateEffects
  });
})();

(() => {
  'use strict';

  // ---------------------------------------------------------------------------
  // Shared shape helpers
  // ---------------------------------------------------------------------------
  function shadow(x, y, s, r = 46, a = 0.5) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s * 0.24);
    const g = ctx.createRadialGradient(0, 0, 2, 0, 0, r);
    g.addColorStop(0, `rgba(0,0,0,${a})`);
    g.addColorStop(0.55, `rgba(0,0,0,${a * 0.55})`);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU); ctx.fill();
    ctx.restore();
  }

  function limb(x1, y1, x2, y2, w, color, cap = 'round') {
    ctx.strokeStyle = color;
    ctx.lineWidth = w;
    ctx.lineCap = cap;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  function joint(x, y, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
  }

  function boot(x, y, angle, s, color = '#090b12') {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(6 * s, 1.4 * s, 12 * s, 4.3 * s, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(210,195,166,0.12)';
    ctx.beginPath();
    ctx.ellipse(9 * s, -0.2 * s, 5 * s, 1.2 * s, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  function scarfWave(anim, speed, dash) {
    const base = Math.sin(anim * 2.1) * 4 + Math.sin(anim * 4.7) * 1.8;
    const len = dash ? 126 : speed ? 92 : 76;
    return { base, len };
  }

  function drawScarf(anim, speed, dash, color = '#b53a34', alpha = 1) {
    const { base, len } = scarfWave(anim, speed, dash);
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.lineCap = 'round';
    const points = [
      { x: -4, y: -132 },
      { x: -26, y: -135 + base * 0.6 },
      { x: -52, y: -124 + base },
      { x: -len, y: -112 + base * 1.8 + (dash ? 8 : 0) }
    ];
    const g = ctx.createLinearGradient(0, -132, -len, -100);
    g.addColorStop(0, color);
    g.addColorStop(0.6, '#8d2528');
    g.addColorStop(1, 'rgba(77,16,23,0.2)');
    ctx.strokeStyle = g;
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    ctx.bezierCurveTo(points[1].x, points[1].y, points[2].x, points[2].y, points[3].x, points[3].y);
    ctx.stroke();
    // lit upper edge
    ctx.strokeStyle = 'rgba(228,96,79,0.5)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(-4, -136);
    ctx.bezierCurveTo(-28, -140 + base * 0.6, -50, -129 + base, -len, -117 + base * 1.8);
    ctx.stroke();
    // torn second tail
    ctx.strokeStyle = 'rgba(95,22,27,0.7)';
    ctx.lineWidth = 4.5;
    ctx.beginPath();
    ctx.moveTo(-4, -128);
    ctx.bezierCurveTo(-35, -120 + base, -58, -108 + base, -len * 0.78, -96 + base * 1.5);
    ctx.stroke();
    ctx.restore();
  }

  function drawKatana(handX, handY, angle, length = 108, glow = 0, color = '#d9d6ca') {
    const dx = Math.cos(angle), dy = Math.sin(angle);
    const px = -dy, py = dx;
    const hx = handX - dx * 19, hy = handY - dy * 19;
    const tipX = handX + dx * length, tipY = handY + dy * length;

    // handle
    ctx.save();
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#171920';
    ctx.lineWidth = 6.5;
    ctx.beginPath(); ctx.moveTo(hx, hy); ctx.lineTo(handX + dx * 3, handY + dy * 3); ctx.stroke();
    ctx.strokeStyle = 'rgba(201,165,104,0.55)';
    ctx.lineWidth = 1;
    for (let i = 1; i < 5; i++) {
      const t = i / 5;
      ctx.beginPath();
      ctx.moveTo(hx + dx * t * 20 - px * 3, hy + dy * t * 20 - py * 3);
      ctx.lineTo(hx + dx * t * 20 + px * 3, hy + dy * t * 20 + py * 3);
      ctx.stroke();
    }
    // guard
    ctx.strokeStyle = '#a88750';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(handX - px * 7, handY - py * 7);
    ctx.lineTo(handX + px * 7, handY + py * 7);
    ctx.stroke();

    // blade
    if (glow > 0) {
      ctx.shadowColor = 'rgba(182,255,248,0.9)';
      ctx.shadowBlur = 10 + glow * 16;
    }
    const grad = ctx.createLinearGradient(handX, handY, tipX, tipY);
    grad.addColorStop(0, '#7f8589');
    grad.addColorStop(0.25, color);
    grad.addColorStop(0.75, '#f2f3ee');
    grad.addColorStop(1, '#b9c4c6');
    ctx.strokeStyle = grad;
    ctx.lineWidth = 4.4;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(handX + dx * 4, handY + dy * 4);
    ctx.quadraticCurveTo(handX + dx * length * 0.55 + px * 2.7, handY + dy * length * 0.55 + py * 2.7, tipX, tipY);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(handX + dx * 8 - px * 1.4, handY + dy * 8 - py * 1.4);
    ctx.quadraticCurveTo(handX + dx * length * 0.55 - px * 0.9, handY + dy * length * 0.55 - py * 0.9, tipX - dx * 2, tipY - dy * 2);
    ctx.stroke();
    // tsuba glint
    ctx.fillStyle = '#d7b477';
    ctx.beginPath(); ctx.arc(handX, handY, 2.2, 0, TAU); ctx.fill();
    ctx.restore();
  }

  function drawSpear(handX, handY, angle, length, glow = 0) {
    const dx = Math.cos(angle), dy = Math.sin(angle);
    const tipX = handX + dx * length, tipY = handY + dy * length;
    ctx.save();
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#2b1d19';
    ctx.lineWidth = 3.4;
    ctx.beginPath(); ctx.moveTo(handX - dx * 55, handY - dy * 55); ctx.lineTo(tipX, tipY); ctx.stroke();
    if (glow > 0) {
      ctx.shadowColor = 'rgba(255,90,70,0.9)';
      ctx.shadowBlur = glow * 12;
    }
    ctx.fillStyle = '#d7d1c1';
    ctx.beginPath();
    ctx.moveTo(tipX + dx * 19, tipY + dy * 19);
    ctx.lineTo(tipX - dy * 4, tipY + dx * 4);
    ctx.lineTo(tipX + dx * 3, tipY + dy * 3);
    ctx.lineTo(tipX + dy * 4, tipY - dx * 4);
    ctx.closePath();
    ctx.fill();
    // red tassel
    ctx.strokeStyle = '#a7312f';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(handX + dx * 12, handY + dy * 12);
    ctx.quadraticCurveTo(handX + dx * 2 - dy * 7, handY + dy * 2 + dx * 7, handX + dx * 36, handY + dy * 36);
    ctx.stroke();
    ctx.restore();
  }

  function drawClub(handX, handY, angle, s = 1, glow = 0) {
    const dx = Math.cos(angle), dy = Math.sin(angle);
    const px = -dy, py = dx;
    ctx.save();
    ctx.translate(handX, handY);
    ctx.rotate(angle);
    if (glow > 0) {
      ctx.shadowColor = 'rgba(255,92,58,0.8)';
      ctx.shadowBlur = glow * 16;
    }
    ctx.fillStyle = '#1b1414';
    ctx.beginPath();
    ctx.moveTo(-42, -2.5);
    ctx.lineTo(10, -5);
    ctx.lineTo(74, -13);
    ctx.quadraticCurveTo(94, 0, 74, 13);
    ctx.lineTo(10, 5);
    ctx.lineTo(-42, 2.5);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(153,108,72,0.4)';
    ctx.lineWidth = 1;
    ctx.stroke();
    // spikes
    ctx.fillStyle = '#b0a38c';
    for (let i = 0; i < 4; i++) {
      const x = 24 + i * 15;
      ctx.beginPath();
      ctx.moveTo(x, -10);
      ctx.lineTo(x + 6, -21);
      ctx.lineTo(x + 10, -9);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  function drawBow(x, y, angle, pull, glow = 0) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    if (glow > 0) {
      ctx.shadowColor = 'rgba(255,90,66,0.6)';
      ctx.shadowBlur = 12;
    }
    ctx.strokeStyle = '#8b6b43';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, -34);
    ctx.quadraticCurveTo(32, 0, 0, 34);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(228,215,190,0.65)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(0, -34);
    ctx.lineTo(-10 - pull * 12, 0);
    ctx.lineTo(0, 34);
    ctx.stroke();
    // arrow
    ctx.strokeStyle = '#d9cdb5';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-14 - pull * 10, 0);
    ctx.lineTo(33, 0);
    ctx.stroke();
    ctx.fillStyle = '#b5aa96';
    ctx.beginPath();
    ctx.moveTo(38, 0); ctx.lineTo(28, -3.6); ctx.lineTo(28, 3.6); ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  // ---------------------------------------------------------------------------
  // Player
  // ---------------------------------------------------------------------------
  function drawPlayer(p) {
    if (!p) return;
    const s = depthScale(p.z);
    const fy = groundY(p.z);
    shadow(p.x, fy, s * 1.01, 55, 0.55);

    if (p.shadow >= 100 && !p.dead) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const aura = ctx.createRadialGradient(p.x, fy - 76 * s, 5, p.x, fy - 76 * s, 95 * s);
      aura.addColorStop(0, 'rgba(121,235,228,0.09)');
      aura.addColorStop(0.6, 'rgba(109,215,210,0.035)');
      aura.addColorStop(1, 'rgba(65,170,180,0)');
      ctx.fillStyle = aura;
      ctx.beginPath(); ctx.arc(p.x, fy - 76 * s, 95 * s, 0, TAU); ctx.fill();
      ctx.restore();
    }

    ctx.save();
    ctx.translate(p.x, fy);
    ctx.scale(p.facing * s, s);
    if (p.dead) {
      const t = clamp((G.deathTimer ?? 0) / 1.4, 0, 1);
      ctx.translate(-15 * t, 0);
      ctx.rotate(-0.75 * t);
    }

    const run = p.state === 'run';
    const dash = p.state === 'dash' || p.state === 'special';
    const attack = p.state === 'attack' ? ATTACKS[p.attackStep - 1] : null;
    const hurt = p.state === 'hurt';
    const kunai = p.state === 'kunai';
    const breathe = Math.sin(p.anim * 2.2) * 1.4;
    let lean = run ? 0.14 : 0.01;
    let crouch = 0;
    let swordAngle = 1.12;
    let swordGlow = 0;
    let armReach = 39;
    let bob = run ? Math.abs(Math.sin(p.runPhase)) * -3.2 : breathe * 0.55;

    if (attack) {
      const spec = attack;
      const q = clamp((p.timer - spec.startup * 0.22) / (spec.startup + spec.active * 0.95), 0, 1);
      const e = easeOut(q);
      if (p.attackStep === 1) swordAngle = lerp(-2.24, 0.92, e);
      else if (p.attackStep === 2) swordAngle = lerp(2.35, -1.18, e);
      else swordAngle = lerp(-2.9, 2.75, e);
      lean = p.attackStep === 3 ? 0.23 : 0.16;
      crouch = p.attackStep === 3 ? 5 : 1.5;
      swordGlow = p.attackStep === 3 ? 1 : 0.55;
      armReach = p.attackStep === 3 ? 48 : 44;
      bob = 0;
    } else if (dash) {
      lean = 0.4;
      crouch = 3;
      swordAngle = 1.48;
      armReach = 45;
      bob = 0;
    } else if (hurt) {
      lean = -0.2;
      swordAngle = 1.5;
      bob = 3;
    } else if (kunai) {
      lean = 0.11;
      swordAngle = 1.3;
      bob = 0;
    }

    const hipY = -70 + crouch;
    let feet;
    if (dash) {
      feet = { back: { x: -17, y: -13 }, front: { x: 37, y: -4 }, backKnee: { x: -25, y: -37 }, frontKnee: { x: 23, y: -35 } };
    } else if (attack) {
      feet = { back: { x: -35, y: 0 }, front: { x: 38, y: 0 }, backKnee: { x: -28, y: -33 }, frontKnee: { x: 32, y: -34 } };
    } else if (run) {
      const swing = Math.sin(p.runPhase) * 22;
      const liftB = Math.max(0, Math.cos(p.runPhase)) * 13;
      const liftF = Math.max(0, -Math.cos(p.runPhase)) * 13;
      feet = {
        back: { x: -18 - swing, y: -liftB },
        front: { x: 18 + swing, y: -liftF },
        backKnee: { x: (-16 - swing) * 0.52 - 5, y: -34 + liftB * 0.3 },
        frontKnee: { x: (16 + swing) * 0.55 + 6, y: -35 + liftF * 0.3 }
      };
    } else if (hurt) {
      feet = { back: { x: -38, y: 0 }, front: { x: 26, y: 0 }, backKnee: { x: -28, y: -34 }, frontKnee: { x: 23, y: -33 } };
    } else {
      const sway = Math.sin(p.anim * 1.15) * 0.8;
      feet = { back: { x: -27 + sway, y: 0 }, front: { x: 29 + sway, y: 0 }, backKnee: { x: -21, y: -35 }, frontKnee: { x: 25, y: -36 } };
    }

    // scarf + coat tails behind
    drawScarf(p.anim, run, dash, p.state === 'special' ? '#6ee5dc' : '#b43a34', p.dead ? 0.3 : 1);
    drawCoatTail(p, run, dash, attack);

    // back arm (behind torso)
    const shoulder = { x: 8, y: -118 + breathe };
    const backShoulder = { x: -12, y: -116 + breathe };
    let backElbow = { x: -25, y: -94 + Math.sin(p.anim * 2.4) * 2 };
    let backHand = { x: -21, y: -77 };
    if (run) {
      const sw = Math.sin(p.runPhase + Math.PI) * 12;
      backElbow = { x: -24 - sw * 0.5, y: -101 };
      backHand = { x: -19 - sw, y: -81 + sw * 0.1 };
    }
    drawSleevedArm(backShoulder, backElbow, backHand, '#0b0d15', '#171c29', 13, 9);

    // Legs
    drawLeg({ x: -9, y: hipY - 3 }, feet.backKnee, feet.back, 17, 13, '#090b12', '#141925');
    drawLeg({ x: 10, y: hipY - 3 }, feet.frontKnee, feet.front, 18, 14, '#0d1019', '#1b2130');
    boot(feet.back.x, feet.back.y, 0.08, 1, '#060810');
    boot(feet.front.x, feet.front.y, -0.03, 1, '#090b12');

    // Upper body, leaning around the hips
    ctx.save();
    ctx.translate(0, hipY);
    ctx.rotate(lean);
    ctx.translate(0, -hipY + bob);

    drawTorso(p, run, hurt, breathe);
    drawHead(p, run, hurt, attack, breathe);

    // Front arm & katana
    let hand, elbow;
    if (kunai) {
      hand = { x: 36, y: -113 };
      elbow = { x: 27, y: -118 };
      swordAngle = 1.3;
    } else {
      hand = {
        x: shoulder.x + Math.cos(swordAngle) * armReach,
        y: shoulder.y + Math.sin(swordAngle) * armReach
      };
      const mx = (shoulder.x + hand.x) / 2;
      const my = (shoulder.y + hand.y) / 2;
      const dx = hand.x - shoulder.x, dy = hand.y - shoulder.y;
      const m = Math.hypot(dx, dy) || 1;
      elbow = { x: mx - dy / m * 7, y: my + dx / m * 7 };
    }
    drawSleevedArm(shoulder, elbow, hand, '#0b0e17', '#202738', 14, 10);
    ctx.fillStyle = '#b8aa91';
    ctx.beginPath(); ctx.arc(hand.x, hand.y, 3.4, 0, TAU); ctx.fill();
    drawKatana(hand.x, hand.y, swordAngle, attack ? 122 : 112, swordGlow);

    if (kunai) {
      ctx.save();
      ctx.translate(hand.x, hand.y);
      ctx.rotate(p.anim * 18);
      ctx.fillStyle = '#d9fbf6';
      ctx.shadowColor = '#7ce7e0';
      ctx.shadowBlur = 10;
      ctx.beginPath();
      for (let i = 0; i < 4; i++) {
        const a = i / 4 * TAU;
        ctx.lineTo(Math.cos(a) * 10, Math.sin(a) * 10);
        ctx.lineTo(Math.cos(a + TAU / 8) * 3, Math.sin(a + TAU / 8) * 3);
      }
      ctx.closePath(); ctx.fill();
      ctx.restore();
    }

    // rim light
    ctx.strokeStyle = 'rgba(136,176,196,0.32)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(-17, -137);
    ctx.quadraticCurveTo(-11, -158, 3, -162);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-20, -126);
    ctx.quadraticCurveTo(-27, -110, -21, -94);
    ctx.stroke();

    ctx.restore();
    ctx.restore();

    if (p.flash > 0.05 && !p.dead) {
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.globalAlpha = p.flash * 0.18;
      ctx.fillStyle = '#ff7a6d';
      ctx.beginPath();
      ctx.ellipse(p.x, fy - 80 * s, 36 * s, 68 * s, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  function drawLeg(hip, knee, foot, thighW, shinW, dark, light) {
    // CLOTH / shell
    limb(hip.x, hip.y, knee.x, knee.y, thighW, dark);
    limb(knee.x, knee.y, foot.x, foot.y, shinW, dark);
    // lit edge
    ctx.strokeStyle = light;
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(hip.x + 4, hip.y - 2);
    ctx.quadraticCurveTo(knee.x + 4, knee.y - 2, foot.x + 2, foot.y - 5);
    ctx.stroke();
    // shin wrap
    ctx.strokeStyle = 'rgba(197,177,143,0.22)';
    ctx.lineWidth = 1;
    for (let i = 1; i < 3; i++) {
      const t = i / 3;
      const x = lerp(knee.x, foot.x, t), y = lerp(knee.y, foot.y, t);
      ctx.beginPath();
      ctx.moveTo(x - 5, y - 1); ctx.lineTo(x + 5, y + 2);
      ctx.stroke();
    }
  }

  function drawCoatTail(p, run, dash, attack) {
    const wave = Math.sin(p.anim * 2.8) * 4;
    const lean = run ? 10 : attack ? 6 : 0;
    ctx.save();
    ctx.fillStyle = '#11151f';
    ctx.beginPath();
    ctx.moveTo(-13, -91);
    ctx.quadraticCurveTo(-37 - lean, -58, -44 - lean, -16 + wave);
    ctx.lineTo(-27, -23 + wave);
    ctx.lineTo(-26, -3 + wave);
    ctx.lineTo(-8, -20);
    ctx.lineTo(5, -68);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(66,84,110,0.3)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-13, -88);
    ctx.quadraticCurveTo(-30 - lean, -56, -35 - lean, -20 + wave);
    ctx.stroke();
    ctx.restore();
  }

  function drawTorso(p, run, hurt, breathe) {
    const g = ctx.createLinearGradient(-24, -130, 26, -70);
    g.addColorStop(0, '#080a11');
    g.addColorStop(0.5, '#111621');
    g.addColorStop(1, '#1c2230');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-22, -127 + breathe);
    ctx.quadraticCurveTo(-28, -104, -17, -76);
    ctx.quadraticCurveTo(-9, -68, 2, -72);
    ctx.quadraticCurveTo(16, -70, 18, -82);
    ctx.quadraticCurveTo(27, -105, 22, -126 + breathe);
    ctx.quadraticCurveTo(9, -136 + breathe, -22, -127 + breathe);
    ctx.closePath();
    ctx.fill();

    // chest wrap
    ctx.fillStyle = 'rgba(58,69,90,0.28)';
    ctx.beginPath();
    ctx.moveTo(-23, -118);
    ctx.lineTo(20, -105);
    ctx.lineTo(16, -96);
    ctx.lineTo(-21, -109);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(159,179,196,0.2)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(-23, -118); ctx.lineTo(20, -105); ctx.stroke();

    // shoulder guard
    ctx.fillStyle = '#161c28';
    ctx.strokeStyle = 'rgba(77,94,117,0.65)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(8, -129 + breathe);
    ctx.lineTo(29, -120 + breathe);
    ctx.lineTo(25, -109);
    ctx.lineTo(17, -116);
    ctx.lineTo(10, -116);
    ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = 'rgba(201,165,104,0.35)';
    ctx.fillRect(14, -123 + breathe, 10, 1.2);

    // sash / belt
    ctx.fillStyle = '#701c23';
    ctx.beginPath();
    ctx.moveTo(-20, -86); ctx.lineTo(20, -82);
    ctx.lineTo(19, -75); ctx.lineTo(-19, -79);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(234,105,83,0.35)';
    ctx.beginPath(); ctx.moveTo(-20, -86); ctx.lineTo(20, -82); ctx.stroke();
    // knot
    ctx.fillStyle = '#9b2c2f';
    ctx.beginPath(); ctx.ellipse(14, -80, 4, 3, -0.2, 0, TAU); ctx.fill();
    ctx.strokeStyle = '#631a22';
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(13, -77);
    ctx.quadraticCurveTo(18 + Math.sin(p.anim * 3) * 3, -59, 7, -46 + Math.sin(p.anim * 2.4) * 2);
    ctx.stroke();

    // armored ribs
    ctx.strokeStyle = 'rgba(88,104,125,0.3)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const y = -104 + i * 7;
      ctx.beginPath();
      ctx.moveTo(-14, y + 2);
      ctx.quadraticCurveTo(0, y + 5, 13, y);
      ctx.stroke();
    }

    // little hanging charm
    ctx.fillStyle = '#c9a568';
    ctx.beginPath(); ctx.arc(-10, -77, 1.7, 0, TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(201,165,104,0.5)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(-10, -75); ctx.lineTo(-12, -62); ctx.stroke();
  }

  function drawHead(p, run, hurt, attack, breathe) {
    const hx = 2 + (run ? 3 : 0) + (attack ? 2 : 0);
    const hy = -147 + breathe + (hurt ? 4 : 0);
    // neck
    ctx.fillStyle = '#0a0c13';
    ctx.fillRect(-4, hy + 14, 10, 11);
    // hood shape
    const g = ctx.createLinearGradient(-13, hy - 14, 18, hy + 12);
    g.addColorStop(0, '#0b0e17');
    g.addColorStop(0.65, '#141a27');
    g.addColorStop(1, '#1e2638');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-9, hy + 7);
    ctx.quadraticCurveTo(-17, hy - 3, -9, hy - 15);
    ctx.quadraticCurveTo(1, hy - 23, 12, hy - 14);
    ctx.quadraticCurveTo(20, hy - 6, 17, hy + 4);
    ctx.quadraticCurveTo(11, hy + 15, -9, hy + 7);
    ctx.closePath();
    ctx.fill();
    // face wrap
    ctx.fillStyle = '#b4a58d';
    ctx.beginPath();
    ctx.moveTo(5, hy - 10);
    ctx.quadraticCurveTo(16, hy - 9, 17, hy + 1);
    ctx.quadraticCurveTo(15, hy + 8, 7, hy + 7);
    ctx.quadraticCurveTo(1, hy + 1, 5, hy - 10);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(36,30,31,0.28)';
    ctx.beginPath();
    ctx.moveTo(8, hy + 3);
    ctx.quadraticCurveTo(14, hy + 2, 16, hy + 1);
    ctx.lineTo(15, hy + 7);
    ctx.quadraticCurveTo(10, hy + 8, 8, hy + 4);
    ctx.fill();
    // eyes
    ctx.save();
    ctx.shadowColor = '#8ff8f0';
    ctx.shadowBlur = 9;
    ctx.fillStyle = '#cffffb';
    ctx.beginPath(); ctx.ellipse(10, hy - 3, 2.5, 1.15, -0.12, 0, TAU); ctx.fill();
    ctx.globalAlpha = 0.5;
    ctx.beginPath(); ctx.ellipse(14.6, hy - 2.5, 1.2, 0.8, -0.12, 0, TAU); ctx.fill();
    ctx.restore();
    // headband
    ctx.strokeStyle = '#9c2d31';
    ctx.lineWidth = 3.3;
    ctx.beginPath();
    ctx.moveTo(-11, hy - 9);
    ctx.quadraticCurveTo(4, hy - 13, 15, hy - 9);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(219,78,64,0.55)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-13, hy - 10);
    ctx.quadraticCurveTo(-30, hy - 18 + Math.sin(p.anim * 3.4) * 4, -44, hy - 12 + Math.sin(p.anim * 3.1) * 3);
    ctx.stroke();
    // hood fold highlight
    ctx.strokeStyle = 'rgba(109,139,164,0.36)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-11, hy - 13);
    ctx.quadraticCurveTo(-2, hy - 22, 9, hy - 16);
    ctx.stroke();
    // shoulder cloth wrap
    ctx.strokeStyle = 'rgba(204,190,164,0.18)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(2, hy + 11); ctx.lineTo(13, hy + 16); ctx.stroke();
  }

  function drawSleevedArm(shoulder, elbow, hand, color, light, w1, w2) {
    limb(shoulder.x, shoulder.y, elbow.x, elbow.y, w1, color);
    limb(elbow.x, elbow.y, hand.x, hand.y, w2, color);
    // highlight
    ctx.strokeStyle = light;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(shoulder.x + 3, shoulder.y - 2);
    ctx.quadraticCurveTo(elbow.x + 3, elbow.y - 2, hand.x + 2, hand.y - 2);
    ctx.stroke();
    // bracer bands
    ctx.strokeStyle = 'rgba(201,165,104,0.28)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 2; i++) {
      const t = 0.64 + i * 0.16;
      const x = lerp(elbow.x, hand.x, t), y = lerp(elbow.y, hand.y, t);
      ctx.beginPath(); ctx.moveTo(x - 3, y - 3); ctx.lineTo(x + 3, y + 2); ctx.stroke();
    }
    joint(hand.x, hand.y, 3.2, '#a9977f');
  }

  // ---------------------------------------------------------------------------
  // Enemies
  // ---------------------------------------------------------------------------
  function drawEnemy(e) {
    if (!e) return;
    const s = depthScale(e.z) * e.cfg.scale;
    const fy = groundY(e.z);
    const deadT = e.dead ? clamp(e.timer / 1.05, 0, 1) : 0;
    const spawnT = e.state === 'spawn' ? clamp(e.timer / e.spawnDuration, 0, 1) : 1;
    const alpha = e.dead ? 1 - deadT * 0.95 : Math.min(1, spawnT * 1.5);
    if (alpha <= 0.01) return;

    shadow(e.x, fy, s, e.cfg.boss ? 74 : 44, 0.6 * alpha);

    if (e.dead) {
      for (let i = 0; i < 2; i++) {
        if (chance(0.1)) {
          spawnParticle({
            x: e.x + rand(20, -20), y: fy - rand(80, 10), z: e.z,
            vx: rand(15, -15), vy: rand(-8, -35), gravity: 10, life: 0.8,
            maxLife: 0.8, size: rand(18, 6), color: '#090b10', kind: 'smoke', alpha: 0.2
          });
        }
      }
    }

    if (e.type === 'archer' && e.state === 'windup') {
      const px = G.player.x, py = groundY(G.player.z) - 80 * depthScale(G.player.z);
      const ex = e.x, ey = fy - 105 * s;
      ctx.save();
      ctx.strokeStyle = `rgba(229,73,60,${0.15 + (e.timer / e.windupT) * 0.3})`;
      ctx.lineWidth = 0.8;
      ctx.setLineDash([3, 8]);
      ctx.beginPath(); ctx.moveTo(ex, ey); ctx.lineTo(px, py); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(e.x, fy);
    ctx.scale(e.facing * s, s);
    if (e.dead) {
      ctx.rotate(-deadT * 1.25);
      ctx.translate(-deadT * 14, 0);
    } else if (e.state === 'spawn') {
      ctx.translate(0, (1 - spawnT) * 16);
    }

    if (e.type === 'archer') drawArcherBody(e);
    else if (e.type === 'brute') drawBruteBody(e, false);
    else if (e.type === 'boss') drawBruteBody(e, true);
    else drawRoninBody(e, e.type === 'spear');

    ctx.restore();

    // spawning smoke
    if (e.state === 'spawn') {
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      const a = 1 - spawnT;
      const gr = ctx.createRadialGradient(e.x, fy - 30, 2, e.x, fy - 30, 80 * s);
      gr.addColorStop(0, `rgba(198,66,47,${0.12 * a})`);
      gr.addColorStop(1, 'rgba(65,20,25,0)');
      ctx.fillStyle = gr;
      ctx.beginPath(); ctx.ellipse(e.x, fy - 20, 90 * s, 38 * s, 0, 0, TAU); ctx.fill();
      ctx.restore();
    }

    if (!e.dead && e.hpBar > 0 && !e.cfg.boss) {
      const w = e.cfg.superArmor ? 64 : 44;
      const barY = fy - 195 * s;
      ctx.save();
      ctx.globalAlpha = clamp(e.hpBar, 0, 1);
      ctx.fillStyle = 'rgba(3,4,8,0.72)';
      ctx.fillRect(e.x - w / 2, barY, w, 3);
      ctx.fillStyle = e.hp / e.maxHp > 0.5 ? '#c44a3e' : '#ff624f';
      ctx.fillRect(e.x - w / 2, barY, w * (e.hp / e.maxHp), 3);
      ctx.restore();
    }

    if (!e.dead && e.state === 'windup') {
      const pulse = 0.65 + Math.sin(G.time * 12) * 0.25;
      const top = fy - (e.cfg.boss ? 310 : e.cfg.superArmor ? 240 : 218) * s;
      ctx.save();
      ctx.translate(e.x, top);
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = `rgba(255,85,62,${pulse})`;
      ctx.beginPath();
      ctx.moveTo(0, -9); ctx.lineTo(6, 0); ctx.lineTo(0, 9); ctx.lineTo(-6, 0);
      ctx.closePath(); ctx.fill();
      ctx.globalAlpha = 0.4;
      ctx.beginPath(); ctx.arc(0, 0, 16 + Math.sin(G.time * 8) * 3, 0, TAU); ctx.fill();
      ctx.restore();
    }
  }

  function drawRoninBody(e, spear) {
    const walk = e.state === 'walk' || e.state === 'idle';
    const phase = e.runPhase;
    const swing = walk ? Math.sin(phase) * 14 : 0;
    const flinch = e.state === 'hurt' ? -0.13 : 0;
    let lean = e.state === 'windup' ? -0.12 : e.state === 'strike' ? 0.2 : 0.05 + flinch;
    const crouch = e.state === 'windup' ? 4 : 0;
    let weaponAngle = 1.25;
    let weaponGlow = 0;
    if (e.state === 'windup') {
      const t = clamp(e.timer / e.windupT, 0, 1);
      weaponAngle = lerp(1.15, -2.2, easeIn(t));
      weaponGlow = t * 0.7;
    } else if (e.state === 'strike') {
      const t = clamp(e.timer / (e.strikeT + 0.05), 0, 1);
      weaponAngle = lerp(-2.2, 1.1, easeOut(t));
      weaponGlow = 0.9;
    } else if (!walk) {
      weaponAngle = 1.15;
    } else {
      weaponAngle = 1.2 + Math.sin(phase) * 0.07;
    }

    const hip = -67 + crouch;
    const footB = { x: -16 - swing, y: 0 };
    const footF = { x: 20 + swing, y: 0 };
    const robeColor = e.flash > 0.04 ? '#f3dfc6' : '#2a1519';
    const robeLit = e.flash > 0.04 ? '#fff4df' : '#53242a';

    drawRaggedCoat(e, robeColor, robeLit, walk ? phase : 0);
    limb(-5, hip - 4, -19 - swing * 0.6, -32, 15, e.flash > 0.04 ? '#e7d3ba' : '#100d13');
    limb(-19 - swing * 0.6, -32, footB.x, footB.y, 10, '#151117');
    limb(7, hip - 4, 20 + swing * 0.65, -33, 16, e.flash > 0.04 ? '#f0dcc4' : '#171117');
    limb(20 + swing * 0.65, -33, footF.x, footF.y, 11, '#1b1318');
    boot(footB.x, footB.y, 0.04, 0.9, '#08070b');
    boot(footF.x, footF.y, -0.04, 0.9, '#0b090c');

    ctx.save();
    ctx.translate(0, hip);
    ctx.rotate(lean);
    ctx.translate(0, -hip);

    // torso
    const g = ctx.createLinearGradient(-20, -120, 20, -70);
    g.addColorStop(0, e.flash > 0.04 ? '#ead6bd' : '#1c1014');
    g.addColorStop(0.6, robeColor);
    g.addColorStop(1, e.flash > 0.04 ? '#fff1d8' : '#31171c');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-21, -126);
    ctx.quadraticCurveTo(-27, -104, -16, -76);
    ctx.lineTo(15, -74);
    ctx.quadraticCurveTo(25, -103, 20, -126);
    ctx.quadraticCurveTo(0, -136, -21, -126);
    ctx.closePath();
    ctx.fill();

    // armor plates
    ctx.fillStyle = 'rgba(71,41,35,0.9)';
    ctx.beginPath();
    ctx.moveTo(-19, -116); ctx.lineTo(18, -110); ctx.lineTo(15, -100); ctx.lineTo(-18, -105); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(201,165,104,0.27)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(-18, -114); ctx.lineTo(17, -108); ctx.stroke();

    // sash
    ctx.fillStyle = '#7e1e21';
    ctx.fillRect(-17, -84, 34, 5);
    ctx.fillStyle = 'rgba(219,94,70,0.45)';
    ctx.fillRect(-17, -84, 34, 1);

    // back arm
    drawSleevedArm({ x: -14, y: -115 }, { x: -28, y: -96 }, { x: -25, y: -78 }, '#140c11', '#3b1d22', 11, 8);

    // head + kasa
    ctx.fillStyle = e.flash > 0.04 ? '#efe1cc' : '#0d0a0e';
    ctx.beginPath(); ctx.arc(4, -146, 13, 0, TAU); ctx.fill();
    // mask
    ctx.fillStyle = e.flash > 0.04 ? '#fff5e2' : '#b8a38a';
    ctx.beginPath();
    ctx.moveTo(7, -152);
    ctx.quadraticCurveTo(17, -150, 17, -141);
    ctx.quadraticCurveTo(14, -134, 8, -136);
    ctx.quadraticCurveTo(3, -142, 7, -152);
    ctx.closePath(); ctx.fill();
    // eyes
    ctx.save();
    ctx.shadowColor = '#ff3f34'; ctx.shadowBlur = 8;
    ctx.fillStyle = '#ff5d4a';
    ctx.beginPath(); ctx.ellipse(10, -146, 2.3, 1, -0.1, 0, TAU); ctx.fill();
    ctx.restore();
    // kasa hat
    const hatY = -158 + (e.state === 'windup' ? -2 : 0);
    ctx.fillStyle = e.flash > 0.04 ? '#e8d5ba' : '#31251d';
    ctx.beginPath();
    ctx.moveTo(0, hatY - 22);
    ctx.lineTo(-9, hatY - 7);
    ctx.quadraticCurveTo(-37, hatY - 1, -42, hatY + 4);
    ctx.quadraticCurveTo(-18, hatY + 11, 0, hatY + 9);
    ctx.quadraticCurveTo(18, hatY + 11, 42, hatY + 4);
    ctx.quadraticCurveTo(37, hatY - 1, 9, hatY - 7);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(182,143,99,0.32)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(-40, hatY + 4); ctx.quadraticCurveTo(0, hatY + 10, 40, hatY + 4); ctx.stroke();
    // hat rim light
    ctx.strokeStyle = 'rgba(190,154,112,0.25)';
    ctx.beginPath(); ctx.moveTo(-29, hatY); ctx.quadraticCurveTo(0, hatY - 5, 29, hatY); ctx.stroke();

    // weapon arm
    const sh = { x: 11, y: -113 };
    const reach = spear ? 54 : 42;
    const hand = { x: sh.x + Math.cos(weaponAngle) * reach, y: sh.y + Math.sin(weaponAngle) * reach };
    const elbow = { x: (sh.x + hand.x) / 2 - 6, y: (sh.y + hand.y) / 2 + 6 };
    drawSleevedArm(sh, elbow, hand, '#1a1015', '#54282b', 12, 8);
    if (spear) drawSpear(hand.x, hand.y, weaponAngle, 176, weaponGlow);
    else drawKatana(hand.x, hand.y, weaponAngle, 102, weaponGlow, '#cfc8b8');

    // telegraph ember on blade
    if (weaponGlow > 0) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const bx = hand.x + Math.cos(weaponAngle) * 70;
      const by = hand.y + Math.sin(weaponAngle) * 70;
      const gr = ctx.createRadialGradient(bx, by, 0, bx, by, 44);
      gr.addColorStop(0, `rgba(255,87,60,${0.32 * weaponGlow})`);
      gr.addColorStop(1, 'rgba(255,60,40,0)');
      ctx.fillStyle = gr;
      ctx.beginPath(); ctx.arc(bx, by, 44, 0, TAU); ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  function drawRaggedCoat(e, color, lit, phase) {
    const flutter = Math.sin(e.anim * 2.4 + phase * 0.4) * 3;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-17, -100);
    ctx.quadraticCurveTo(-31, -57, -27 - flutter, -16);
    ctx.lineTo(-16, -25 + flutter);
    ctx.lineTo(-13, -7);
    ctx.lineTo(-3, -28);
    ctx.lineTo(8, -14 + flutter);
    ctx.lineTo(15, -56);
    ctx.lineTo(17, -92);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = lit;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-17, -95); ctx.quadraticCurveTo(-27, -54, -23, -20); ctx.stroke();
  }

  function drawArcherBody(e) {
    const walk = e.state === 'walk' || e.state === 'idle';
    const phase = e.runPhase;
    const swing = walk ? Math.sin(phase) * 12 : 0;
    const pull = e.state === 'windup' ? clamp(e.timer / e.windupT, 0, 1) : e.state === 'strike' ? 1 : 0;
    const lean = e.state === 'windup' ? -0.08 : 0.08;
    const hip = -68;
    const flash = e.flash > 0.04;
    const dark = flash ? '#f1ddc2' : '#0c1313';
