  function worldTransform(parallax = 1, shake = 1) {
    ctx.translate(view.W / 2, 0);
    ctx.scale(view.scale * G.zoom, view.scale * G.zoom);
    ctx.translate(-G.cam.x * parallax + G.shakeX * shake, -G.cam.y + G.shakeY * shake);
