    dom.flash.style.mixBlendMode = color === '#8ff4ee' ? 'screen' : 'screen';
  }

  function slowTime(seconds = 0.55) {
    G.slowmo = Math.max(G.slowmo, seconds);
    dom.slowVignette.classList.add('active');
  }

